window.AI_CURRICULUM_4 = [{"id":"shapesaroundus4","index":0,"name":"Shapes Around Us","subtitle":"Computational Thinking — Chapter 1","emoji":"🔷","palette":{"from":"#60a5fa","to":"#1e3a8a"},"lessons":[{"id":"sa1","title":"2D Shape Detectives","icon":"🔺","kind":"lesson","story":"You wake up in Flatland, a world made only of flat shapes! The Shape Gatekeeper won't let you through the gate until you can name shapes just from clues about their sides and corners.","teach":[{"title":"What is a 2D shape?","body":"A 2D shape is flat, like a drawing on paper. We describe it by counting its sides (straight edges) and corners (points where two sides meet).","visual":"🔺"},{"title":"Focus on the key clues","body":"Computational thinkers use Abstract Thinking — they ignore color and size, and focus only on the important clues like number of sides and whether the angles are equal.","visual":"🧠"}],"questions":[{"kind":"mcq","prompt":"A shape has exactly 3 straight sides and 3 corners. What shape is it?","options":["Triangle","Hexagon","Square","Pentagon"],"answer":0,"explain":"A shape with 3 sides and 3 corners is always a triangle."},{"kind":"numeric","prompt":"How many corners does a hexagon have?","answer":6,"explain":"Hexa means six, so a hexagon has 6 sides and 6 corners."},{"kind":"mcq","prompt":"Riya draws a shape with 4 sides that are all equal in length, and all 4 angles are right angles (90°). What shape did she draw?","options":["Trapezium","Square","Rhombus","Rectangle"],"answer":1,"explain":"A rectangle also has right angles, but only a square has right angles AND all sides equal."},{"kind":"mcq","prompt":"Which shape can roll smoothly in every direction because it has no straight sides and no corners at all?","options":["Circle","Square","Rectangle","Triangle"],"answer":0,"explain":"A circle is perfectly round with no corners, so it rolls easily."},{"kind":"numeric","prompt":"A pentagon has how many straight sides?","answer":5,"explain":"Penta means five, so a pentagon has 5 sides."}]},{"id":"sa2","title":"3D Shape Explorers","icon":"🧊","kind":"lesson","story":"The gate opens into Blockville, a city built entirely of solid 3D shapes! To cross the city safely, you must count the faces, edges, and corners of every block you meet.","teach":[{"title":"Faces, edges and corners","body":"A 3D shape has faces (flat or curved surfaces), edges (the lines where two faces meet), and corners or vertices (the points where edges meet).","visual":"🧊"},{"title":"Break it into parts","body":"This is Decomposition — a key CT skill! Instead of looking at a whole solid shape at once, break it into its faces, edges, and corners to understand and count it easily.","visual":"🧩"}],"questions":[{"kind":"numeric","prompt":"A cube has how many flat faces in total?","answer":6,"explain":"A cube is like a dice — it has 6 square faces."},{"kind":"numeric","prompt":"A cube has how many edges in total?","answer":12,"explain":"A cube has 12 edges — 4 on the top, 4 on the bottom, and 4 standing up between them."},{"kind":"mcq","prompt":"Which 3D shape has exactly one flat circular face, one curved face, and comes to a point (apex) at the top?","options":["Cube","Cone","Sphere","Cylinder"],"answer":1,"explain":"A cone, like an ice-cream cone, has a flat circle at the base and narrows to a point at the top."},{"kind":"numeric","prompt":"A triangular pyramid has a triangle-shaped base and 3 slanted triangle faces going up to a point. How many faces does it have in total (counting the base)?","answer":4,"explain":"1 triangular base + 3 slanted triangle faces = 4 faces."},{"kind":"mcq","prompt":"Amit is building a cuboid (like a brick) with clay. How many corners (vertices) will it have?","options":["8","12","6","4"],"answer":0,"explain":"A cuboid, just like a cube, has 8 corners."}]},{"id":"sa3","title":"Views From Everywhere","icon":"👀","kind":"lesson","story":"A giant statue blocks your path in Blockville Square. It looks different to everyone standing around it — can you figure out what it looks like from the top, front and side?","teach":[{"title":"Same object, different views","body":"A solid object can look completely different depending on where you stand. Looking at a can from the top shows a circle, but looking at it from the side shows a rectangle!","visual":"👀"},{"title":"Imagine the viewpoint","body":"This uses Abstract Thinking and Pattern Recognition — imagining how a shape would look from a viewpoint you are not standing at, using only the clues you already know about it.","visual":"🔄"}],"questions":[{"kind":"mcq","prompt":"If you look straight down at a cylinder (like a can) from the TOP, what shape do you see?","options":["Circle","Square","Rectangle","Triangle"],"answer":0,"explain":"The top of a cylinder is a flat circle."},{"kind":"mcq","prompt":"You look at a cube from directly in FRONT of it. What shape does the face you see look like?","options":["Triangle","A long rectangle","Square","Circle"],"answer":2,"explain":"Every face of a cube is a square, so the front view is a square."},{"kind":"mcq","prompt":"A cone is placed on a table, point facing up. Looking at it from the SIDE, what shape do you see?","options":["A circle","A square","A triangle","A rectangle"],"answer":2,"explain":"The sloping sides of a cone look like a triangle when viewed from the side."},{"kind":"mcq","prompt":"Priya looks at a closed matchbox (a cuboid) from the TOP, and her friend looks at the SAME matchbox from the FRONT. Both see a rectangle, but the two rectangles are different sizes. Why?","options":["Because the matchbox has different length, breadth and height, so different faces make different sized rectangles","Because a matchbox has no faces","Because one of them is not looking properly","Because the matchbox changed shape"],"answer":0,"explain":"A cuboid's faces are not all the same size, so different views can show different sized rectangles."},{"kind":"mcq","prompt":"A ball (sphere) is looked at from the top, the side, and the front. What shape will be seen from EVERY direction?","options":["A different shape each time","Square","Triangle","Circle"],"answer":3,"explain":"A sphere looks exactly the same round circle from any direction you look at it."}]},{"id":"sa4","title":"Flips and Turns","icon":"🔄","kind":"lesson","story":"You enter the Hall of Mirrors, where every letter and number gets spun and flipped! The mischievous Mirror Imp will only let you pass if you can predict what each symbol turns into.","teach":[{"title":"Turning (rotating) a shape","body":"Rotating a shape means spinning it around a fixed point, like turning a steering wheel. If you rotate something 180°, it ends up completely upside down.","visual":"🔁"},{"title":"Flipping (mirroring) a shape","body":"Flipping a shape makes its mirror image, like holding it up to a mirror or folding paper in half. Left and right swap places, just like your reflection waves back with the opposite hand!","visual":"🪞"}],"questions":[{"kind":"mcq","prompt":"If you rotate the letter 'n' by 180° (turn it fully upside down), which letter does it become?","options":["u","h","w","m"],"answer":0,"explain":"Turn 'n' upside down and its curve now opens upward, forming a 'u'."},{"kind":"mcq","prompt":"You hold the letter 'b' up to a mirror (a left-right flip). Which letter do you see in the mirror?","options":["q","p","d","g"],"answer":2,"explain":"Flipping 'b' left-right swaps its straight line to the other side, making it look like 'd'."},{"kind":"mcq","prompt":"If you rotate the digit '6' by 180°, which digit does it become?","options":["8","9","0","6"],"answer":1,"explain":"Turning '6' fully upside down makes its loop appear at the top, forming a '9'."},{"kind":"mcq","prompt":"If you rotate the letter 'S' by 180°, what do you get?","options":["S (the same letter)","Z","2","5"],"answer":0,"explain":"The letter S is balanced around its center, so turning it upside down gives you an S again."},{"kind":"mcq","prompt":"Which of these capital letters looks EXACTLY the same after a left-right mirror flip?","options":["G","J","A","F"],"answer":2,"explain":"The letter A is symmetric down the middle, so its left and right halves match perfectly in a mirror."}]},{"id":"sa5","title":"Mirror Magic","icon":"🦋","kind":"lesson","story":"Deep in Butterfly Meadow, every creature is perfectly symmetric. The Meadow Fairy will grant you passage only if you can find the fold lines that make both halves match.","teach":[{"title":"Lines of symmetry","body":"A shape has a line of symmetry if you can fold it in half along that line and both halves match perfectly — just like a butterfly's two wings.","visual":"🦋"},{"title":"Spot the matching halves","body":"This uses Pattern Recognition — quickly spotting whether two halves of a shape are mirror images of each other helps you find symmetry fast.","visual":"✨"}],"questions":[{"kind":"numeric","prompt":"A square has how many lines of symmetry (ways to fold it in half so both sides match exactly)?","answer":4,"explain":"A square can be folded along 2 diagonals, 1 vertical line, and 1 horizontal line — 4 lines in total."},{"kind":"numeric","prompt":"An equilateral triangle (all 3 sides equal) has how many lines of symmetry?","answer":3,"explain":"Each line goes from one corner to the middle of the opposite side — there are 3 such lines."},{"kind":"mcq","prompt":"Which of these capital letters has a horizontal line of symmetry (fold it top-to-bottom and both halves match)?","options":["B","R","F","P"],"answer":0,"explain":"The letter B's top loop and bottom loop mirror each other perfectly across a horizontal fold."},{"kind":"mcq","prompt":"A circle has how many lines of symmetry?","options":["Only 4 lines","No lines at all","Only 1 line","Infinite (countless) lines"],"answer":3,"explain":"Any line passing through the center of a circle divides it into two matching halves, so it has infinite lines of symmetry."},{"kind":"mcq","prompt":"Meera folds a paper exactly in half and cuts a heart shape along the fold, then opens it up. What does this show about the heart shape?","options":["It is symmetric — both halves match along the fold line","It has no symmetry at all","It became a completely different shape","It has exactly 4 lines of symmetry"],"answer":0,"explain":"Cutting along a fold always produces a shape that is symmetric along that fold line."}]},{"id":"sa6","title":"Pattern Puzzle Path","icon":"🧩","kind":"lesson","story":"A stone path of shapes stretches ahead, but some stones are missing! Only by spotting the pattern — and the shape that doesn't belong — can you complete the path.","teach":[{"title":"Finding patterns","body":"Pattern Recognition means looking at how shapes change step by step — like gaining one more side each time — so you can predict what comes next.","visual":"🔍"},{"title":"Spot the odd one out","body":"Group shapes by what they share, like number of sides or corners, and then spot the one shape that breaks the rule.","visual":"❓"}],"questions":[{"kind":"mcq","prompt":"A pattern of shapes goes: Triangle (3 sides), Square (4 sides), Pentagon (5 sides), ?. What comes next?","options":["Hexagon (6 sides)","Rectangle (4 sides)","Circle (0 sides)","Triangle (3 sides) again"],"answer":0,"explain":"Each shape in the pattern gains one more side than the last, so a 6-sided hexagon comes next."},{"kind":"numeric","prompt":"Look at this pattern of side-counts: 3, 5, 7, 9, ?. What number comes next?","answer":11,"explain":"The pattern increases by 2 each time: 3, 5, 7, 9, 11."},{"kind":"mcq","prompt":"Find the ODD one out: Square, Rectangle, Rhombus, Circle. Which one does not belong?","options":["Square","Rectangle","Circle (it has no straight sides or corners)","Rhombus"],"answer":2,"explain":"A square, rectangle, and rhombus all have 4 straight sides and 4 corners — but a circle has none."},{"kind":"mcq","prompt":"Find the ODD one out based on number of corners: Triangle, Square, Circle, Pentagon.","options":["Square","Pentagon","Triangle","Circle (it has 0 corners while the others all have straight-sided corners)"],"answer":3,"explain":"A triangle, square, and pentagon all have straight sides and corners — a circle has neither."},{"kind":"mcq","prompt":"A pattern repeats like this: Circle, Square, Triangle, Circle, Square, Triangle, Circle, ?. What comes next?","options":["Square","Triangle","Circle","Pentagon"],"answer":0,"explain":"The pattern repeats every 3 shapes: Circle, Square, Triangle — so after Circle comes Square."}]},{"id":"sa-boss","title":"Warp, the Shape-Shifter","icon":"🐉","kind":"boss","story":"At the heart of Flatland's kingdom waits Warp, a swirling creature made of every shape you've mastered. Defeat Warp by answering its riddles about sides, faces, views, flips, and patterns!","boss":{"name":"Warp, the Shape-Shifter","taunt":"You think you know your circles from your squares? Let's see if your brain can keep up with my twists and turns!"},"questions":[{"kind":"numeric","prompt":"How many flat faces does a cube have in total?","answer":6,"explain":"A cube has 6 square faces, like a dice."},{"kind":"mcq","prompt":"A shape has 4 sides with opposite sides equal, and all angles are right angles, but not all 4 sides are equal. What shape is it?","options":["Square","Rhombus","Trapezium","Rectangle"],"answer":3,"explain":"A rectangle has right angles and equal opposite sides, but its length and breadth can differ."},{"kind":"mcq","prompt":"If you rotate the digit '6' by 180°, what digit do you get?","options":["8","9","0","6"],"answer":1,"explain":"Turning '6' fully upside down makes it look like '9'."},{"kind":"numeric","prompt":"A triangular pyramid has 3 edges around its triangle base, plus 3 edges going up to its top point. How many edges does it have in total?","answer":6,"explain":"3 base edges + 3 slanted edges = 6 edges in total."},{"kind":"mcq","prompt":"Looking at a cylinder (like a can) from directly above, what shape do you see?","options":["Circle","Square","Rectangle","Triangle"],"answer":0,"explain":"The top of a cylinder is a flat circle."},{"kind":"mcq","prompt":"Find the ODD one out: Cube, Sphere, Cone, Square.","options":["Sphere","Cube","Cone","Square (it is a flat 2D shape, while the others are solid 3D shapes)"],"answer":3,"explain":"A cube, sphere, and cone are all solid 3D shapes, but a square is a flat 2D shape."},{"kind":"numeric","prompt":"A regular hexagon (all 6 sides equal) has how many lines of symmetry?","answer":6,"explain":"A regular hexagon has 6 lines of symmetry — 3 through opposite corners and 3 through opposite sides."}]}]},{"id":"hideandseek4","index":1,"name":"Hide and Seek","subtitle":"Computational Thinking — Chapter 2","emoji":"🔍","palette":{"from":"#34d399","to":"#065f46"},"lessons":[{"id":"hs1","title":"The Alley of Ten Doors","icon":"🚪","kind":"lesson","story":"A crumpled map leads you into Shadow Lane, where a row of doors hides shiny coins. An old riddle warns that some doors are cursed and must be skipped — read the rule carefully, walk the whole lane in order, and count every coin you're allowed to take!","teach":[{"title":"Follow the Rule, Step by Step","body":"An algorithm is a list of steps done in order. When a puzzle gives you a rule like 'skip the door after every marked door', walk through the WHOLE path checking the rule at each step, one door at a time.","visual":"🧭"},{"title":"Watch for the Edge","body":"Sometimes a rule points to a door that doesn't exist, like 'the door after the very last door'. A careful thinker checks whether that door is even there before counting it!","visual":"⚠️"}],"questions":[{"kind":"numeric","prompt":"There are 10 doors in a row, numbered 1 to 10. Sam walks from door 1 to door 10 in order, taking a coin from every door EXCEPT the door immediately after door 3, and the door immediately after door 7. How many coins does he collect?","answer":8,"explain":"Doors 4 and 8 are skipped (right after doors 3 and 7), so 10 − 2 = 8 coins."},{"kind":"mcq","prompt":"There are 9 blocks in a row, numbered 1 to 9. Blocks 2, 5, and 8 are painted GREY. Sam walks from block 1 to block 9, picking up a coin from every block EXCEPT the block that comes immediately after a grey block. How many coins does he collect?","options":["6","8","5","7"],"answer":0,"explain":"Blocks 3, 6, and 9 are skipped (right after each grey block), so 9 − 3 = 6 coins."},{"kind":"numeric","prompt":"There are 6 blocks in a row, numbered 1 to 6. Blocks 3 and 6 are painted grey. Sam collects a coin from every block EXCEPT the one immediately after a grey block. Remember: if there is no block after the last one, nothing is skipped there! How many coins does he collect?","answer":5,"explain":"Only block 4 (right after block 3) is skipped — there is no block 7 after block 6, so nothing is skipped there. 6 − 1 = 5 coins."},{"kind":"mcq","prompt":"Which sentence best describes what an ALGORITHM is?","options":["A random guess about the answer","A drawing of a maze","Something only computers can use","A set of clear steps, followed in order, to complete a task"],"answer":3,"explain":"An algorithm is simply an ordered list of steps for doing something."}]},{"id":"hs2","title":"Turn by Turn","icon":"🦯","kind":"lesson","story":"The garden maze has 20 numbered stepping-stones laid in a single winding path. A clever fox left hopping instructions carved into a stone. Trace each hop exactly, one at a time, to find where it finally lands!","teach":[{"title":"Tracing an Algorithm","body":"To trace a set of instructions, start at the beginning and follow each step one at a time, keeping track of where you are right now. Add for 'forward' and subtract for 'back' — never jump ahead!","visual":"🦊"}],"questions":[{"kind":"numeric","prompt":"A fox starts on stone 1 of the 20-stone path. It hops: forward 4, forward 3, back 2, forward 5. Which stone does it land on?","answer":11,"explain":"1 + 4 = 5, + 3 = 8, − 2 = 6, + 5 = 11."},{"kind":"numeric","prompt":"A fox starts on stone 20 (the last stone). It hops: back 5, back 2, forward 1, back 4. Which stone does it land on?","answer":10,"explain":"20 − 5 = 15, − 2 = 13, + 1 = 14, − 4 = 10."},{"kind":"mcq","prompt":"A rabbit starts on stone 6. It hops: forward 3, forward 3, back 1, forward 2, back 5. Which stone does it end on?","options":["13","3","8","11"],"answer":2,"explain":"6+3=9, +3=12, −1=11, +2=13, −5=8."},{"kind":"mcq","prompt":"If an instruction says 'forward 4' and the very next one says 'back 4', where do you end up compared to where you started?","options":["You cannot tell","4 stones ahead","Exactly where you started","4 stones behind"],"answer":2,"explain":"Forward 4 then back 4 cancel each other out, so you return to the same stone."}]},{"id":"hs3","title":"Who's Hiding Where?","icon":"🕵️","kind":"lesson","story":"It's hide-and-seek at Grandma's house! Mia, Kabir, Zara, and Ayaan have each tucked themselves into a different room — the Kitchen, the Garden, the Attic, and the Basement. Read every clue closely, and don't stop searching until you've placed all four!","teach":[{"title":"Cracking Clues with Logic","body":"A detective uses clues one at a time, crossing out what CAN'T be true, until only one answer is left for each person. Some clues tell you exactly where someone is; others only rule out places — use both kinds!","visual":"🕵️"}],"questions":[{"kind":"mcq","prompt":"Clues: Kabir hides in the Garden. Ayaan hides in the Kitchen. Zara does not hide in the Attic or the Kitchen. Mia does not hide in the Basement. Where does Mia hide?","options":["Garden","Kitchen","Attic","Basement"],"answer":2,"explain":"Garden and Kitchen are taken, and Zara can't take the Attic, so Zara must be in the Basement, leaving the Attic for Mia."},{"kind":"mcq","prompt":"Same clues: Kabir hides in the Garden. Ayaan hides in the Kitchen. Zara does not hide in the Attic or the Kitchen. Mia does not hide in the Basement. Where does Zara hide?","options":["Basement","Kitchen","Attic","Garden"],"answer":0,"explain":"With Garden and Kitchen already taken, Zara can't be in the Attic either, so the only room left for her is the Basement."},{"kind":"mcq","prompt":"Same four friends and clues as before. Which friend hides in the Kitchen?","options":["Kabir","Zara","Mia","Ayaan"],"answer":3,"explain":"The clue says directly: Ayaan hides in the Kitchen."},{"kind":"mcq","prompt":"Which ONE clue, all by itself, tells you exactly where Kabir is hiding, without needing any other clue?","options":["Ayaan hides in the Kitchen.","Kabir hides in the Garden.","Mia does not hide in the Basement.","Zara does not hide in the Attic or the Kitchen."],"answer":1,"explain":"This clue names Kabir's exact room directly, so no elimination is needed for it."}]},{"id":"hs4","title":"Recipe for a Perfect Hiding Spot","icon":"🧩","kind":"lesson","story":"Grandpa taught you his legendary 'invisible hider' routine, but the instructions got shuffled in the wind! A good hider always follows steps in the right order — put your thinking cap on and sort it out.","teach":[{"title":"Decomposing a Task into Steps","body":"Decomposition means breaking a big task into small steps. But the steps must also happen in the right ORDER — doing them out of sequence can wreck the whole plan, like trying to close a box before putting anything inside it!","visual":"🧩"}],"questions":[{"kind":"mcq","prompt":"Which order makes the most sense for hiding under the stairs?","options":["Check no one is watching, sneak to the stairs, crawl under the stairs, stay still","Stay still, crawl under the stairs, sneak to the stairs, check no one is watching","Crawl under the stairs, check no one is watching, stay still, sneak to the stairs","Sneak to the stairs, stay still, check no one is watching, crawl under the stairs"],"answer":0,"explain":"You must check first, then sneak over, then crawl in, then finally stay still and quiet."},{"kind":"mcq","prompt":"When writing an algorithm to search for your hidden friends, which should be the very FIRST step?","options":["Count how many friends you found","Decide where you will start searching","Ask a friend if you have won","Celebrate finding everyone"],"answer":1,"explain":"Every algorithm needs a clear starting point before any other step can happen."},{"kind":"numeric","prompt":"A treasure hunt algorithm works like this: read a clue, go to that spot, find the next clue there — and this cycle repeats for every clue before the treasure box is opened. If there are 6 clues in total before the treasure box, how many times does the 'go to the spot and find the next clue' cycle repeat?","answer":6,"explain":"The cycle repeats once for each of the 6 clues, so it repeats 6 times."},{"kind":"mcq","prompt":"Why is the ORDER of steps important in an algorithm?","options":["Only the very first step matters","Doing steps out of order can make the whole plan fail","Order never matters at all","Steps can always be skipped freely"],"answer":1,"explain":"Steps often depend on earlier steps being done first, so the order matters a lot."}]},{"id":"hs5","title":"Arrows in the Dark","icon":"➡️","kind":"lesson","story":"In the Whispering Woods, hidden signs point from one spot to another. Some hideouts get pointed to again and again — spot the pattern to find where everyone is being led!","teach":[{"title":"Finding Patterns by Counting","body":"Pattern Recognition means noticing what repeats most often. When you have many small facts (like a list of arrows), it helps to count how many times each thing appears — almost like keeping tally marks.","visual":"🔢"}],"questions":[{"kind":"mcq","prompt":"Six signs point between four hideouts: Oak Tree → Cave, Rock → Cave, Pond → Rock, Cave → Pond, Rock → Pond, Oak Tree → Pond. Which hideout has the MOST arrows pointing TO it?","options":["Oak Tree","Rock","Cave","Pond"],"answer":3,"explain":"Pond gets arrows from Cave, Rock, and Oak Tree — 3 in total, more than any other hideout."},{"kind":"numeric","prompt":"Same signs: Oak Tree → Cave, Rock → Cave, Pond → Rock, Cave → Pond, Rock → Pond, Oak Tree → Pond. How many arrows point TO the Cave?","answer":2,"explain":"Only Oak Tree → Cave and Rock → Cave point to the Cave, so that's 2."},{"kind":"numeric","prompt":"Same signs: Oak Tree → Cave, Rock → Cave, Pond → Rock, Cave → Pond, Rock → Pond, Oak Tree → Pond. How many arrows point TO the Oak Tree?","answer":0,"explain":"No arrow in the list ends at Oak Tree, so the count is 0."},{"kind":"mcq","prompt":"Same signs: Oak Tree → Cave, Rock → Cave, Pond → Rock, Cave → Pond, Rock → Pond, Oak Tree → Pond. Which hideout has NO arrows pointing to it at all?","options":["Pond","Cave","Rock","Oak Tree"],"answer":3,"explain":"Every arrow starts from Oak Tree but none ever points to it, so it has zero incoming arrows."}]},{"id":"hs6","title":"The Great Coin Count","icon":"🪙","kind":"lesson","story":"Four hiders found treasure chests holding 1, 2, 3, and 4 coins — but nobody remembers who got which chest! Only a handful of clues survive. Think it through carefully, and figure out exactly how many coins each hider has.","teach":[{"title":"Abstract Thinking with Numbers","body":"Abstract thinking means focusing only on the facts that matter and testing possibilities in your head. Try each possible arrangement against every clue — if even one clue breaks, that arrangement is wrong!","visual":"🧠"}],"questions":[{"kind":"numeric","prompt":"Four friends — Priya, Om, Vik, and Naina — have 1, 2, 3, and 4 coins between them, no two the same. Clues: Naina has more coins than Vik. Om has exactly 2 more coins than Priya. Vik has more than 1 coin. How many coins does Priya have?","answer":1,"explain":"Om = Priya + 2 only works as (Priya=1, Om=3) once we also need Vik>1, which rules out the other option; then Vik=2 and Naina=4."},{"kind":"numeric","prompt":"Same friends and clues: Naina has more coins than Vik. Om has exactly 2 more coins than Priya. Vik has more than 1 coin. How many coins does Om have?","answer":3,"explain":"With Priya = 1, Om = Priya + 2 = 3."},{"kind":"mcq","prompt":"Same friends and clues: Naina has more coins than Vik. Om has exactly 2 more coins than Priya. Vik has more than 1 coin. Who ends up with the MOST coins?","options":["Vik","Priya","Om","Naina"],"answer":3,"explain":"The only arrangement that fits every clue is Priya=1, Vik=2, Om=3, Naina=4, so Naina has the most."},{"kind":"numeric","prompt":"Same friends and clues: Naina has more coins than Vik. Om has exactly 2 more coins than Priya. Vik has more than 1 coin. How many coins does Vik have?","answer":2,"explain":"The leftover numbers after Priya=1 and Om=3 are 2 and 4; since Naina must be more than Vik, Vik=2 and Naina=4."}]},{"id":"hs-boss","title":"Final Boss: The Shadow Keeper","icon":"👻","kind":"boss","story":"The Shadow Keeper guards the last hiding place in the game, mixing paths, clues, patterns, and puzzles all together. Prove you've mastered every trick of Hide and Seek to win!","teach":[{"title":"Mix Every Skill You've Learned","body":"The Shadow Keeper's puzzles combine path-tracing, logical clues, pattern counting, and number deduction. Take your time, work through each one step by step, just like you practiced.","visual":"👻"}],"boss":{"name":"The Shadow Keeper","taunt":"You've found doors and hideouts before, but can you out-think the Keeper of Shadows?"},"questions":[{"kind":"numeric","prompt":"There are 12 blocks in a row, numbered 1 to 12. Blocks 4, 7, and 10 are grey. Walking from block 1 to block 12, you collect a coin from every block EXCEPT the block immediately after a grey block. How many coins do you collect?","answer":9,"explain":"Blocks 5, 8, and 11 are skipped (right after each grey block), so 12 − 3 = 9 coins."},{"kind":"numeric","prompt":"On a 20-stone path, a frog starts on stone 10 and hops: forward 6, back 3, forward 2, back 7, forward 1. Which stone does it land on?","answer":9,"explain":"10+6=16, −3=13, +2=15, −7=8, +1=9."},{"kind":"mcq","prompt":"Four friends — Rhea, Dev, Sana, and Kiran — hide in the Loft, Shed, Pantry, and Treehouse. Clues: Rhea hides in the Treehouse. Sana hides in the Shed. Dev does not hide in the Pantry or the Shed. Who hides in the Pantry?","options":["Rhea","Sana","Dev","Kiran"],"answer":3,"explain":"Treehouse and Shed are taken, and Dev can't take the Pantry, so Dev must be in the Loft, leaving the Pantry for Kiran."},{"kind":"numeric","prompt":"Five signs point between hideouts: Hut → Bridge, Bridge → Well, Cliff → Well, Hut → Well, Well → Bridge. How many arrows point TO the Well?","answer":3,"explain":"Bridge → Well, Cliff → Well, and Hut → Well all point to the Well, so that's 3."},{"kind":"mcq","prompt":"Put these hide-and-seek steps in the correct order: 'count to 20', 'seeker closes eyes', 'hide', 'seeker searches'.","options":["Seeker closes eyes, count to 20, hide, seeker searches","Hide, seeker closes eyes, count to 20, seeker searches","Seeker searches, hide, count to 20, seeker closes eyes","Count to 20, hide, seeker closes eyes, seeker searches"],"answer":0,"explain":"The seeker must close their eyes first, then count while others hide, and only then start searching."},{"kind":"numeric","prompt":"Four friends — Tara, Sam, Ravi, and Ila — have 1, 2, 3, and 4 coins, no two the same. Clues: Sam has exactly 2 more coins than Tara. Tara does not have 1 coin. Ravi has fewer coins than Ila. How many coins does Sam have?","answer":4,"explain":"Since Tara can't be 1, Tara must be 2 and Sam = Tara + 2 = 4; the leftover 1 and 3 then split as Ravi=1, Ila=3."},{"kind":"mcq","prompt":"Which computational thinking skill helps you notice that something, like arrows or clues, repeats in a pattern?","options":["Pattern Recognition","Decomposition","Abstract Thinking","Algorithmic Thinking"],"answer":0,"explain":"Pattern Recognition is the skill of spotting things that repeat or happen often."}]}]},{"id":"patternsaroundus4","index":2,"name":"Patterns Around Us","subtitle":"Computational Thinking — Chapter 3","emoji":"🔢","palette":{"from":"#f472b6","to":"#831843"},"lessons":[{"id":"pa1","title":"The Number Bridge","icon":"🌉","kind":"lesson","story":"A rickety bridge of glowing number-stones blocks the path into Pattern Valley. The bridge keeper says a stone will only appear if you can guess the number hiding on it. Study the stones you can already see — they always follow one secret rule!","teach":[{"title":"What is a Number Pattern?","body":"A number pattern is a list of numbers that follow the same rule every time, like 'add 3' or 'subtract 5'. Once you find the rule, you can predict the next number without anyone telling you!","visual":"🔁"}],"questions":[{"kind":"numeric","prompt":"Find the missing stone: 3, 6, 9, 12, ?","answer":15,"explain":"The rule is 'add 3' each time, so 12 + 3 = 15."},{"kind":"numeric","prompt":"Find the missing stone: 5, 10, 15, 20, ?","answer":25,"explain":"The rule is 'add 5' each time, so 20 + 5 = 25."},{"kind":"numeric","prompt":"Find the missing stone: 2, 4, 8, 16, ?","answer":32,"explain":"The rule is 'double the number', so 16 x 2 = 32."},{"kind":"numeric","prompt":"Find the missing stone: 50, 45, 40, 35, ?","answer":30,"explain":"The rule is 'subtract 5' each time, so 35 - 5 = 30."}]},{"id":"pa2","title":"The Growing Staircase","icon":"🪜","kind":"lesson","story":"Beyond the bridge, a magical staircase keeps building itself. Each step is a little taller than the jump before it. If you can guess how big the next jump will be, the staircase will let you climb higher into the valley.","teach":[{"title":"Patterns That Grow","body":"In some patterns, the gap between numbers is not always the same — it grows! For example, in 1, 2, 4, 7 the gaps are +1, then +2, then +3. Spot how the gap itself is changing to find what comes next.","visual":"📈"}],"questions":[{"kind":"numeric","prompt":"The gaps grow by one each time. What comes next? 1, 2, 4, 7, 11, ?","answer":16,"explain":"The gaps are +1, +2, +3, +4, so the next gap is +5: 11 + 5 = 16."},{"kind":"numeric","prompt":"The gaps grow by one each time. What comes next? 2, 4, 7, 11, 16, ?","answer":22,"explain":"The gaps are +2, +3, +4, +5, so the next gap is +6: 16 + 6 = 22."},{"kind":"numeric","prompt":"This is the 'staircase of dots' pattern. What comes next? 1, 3, 6, 10, 15, ?","answer":21,"explain":"The gaps are +2, +3, +4, +5, so the next gap is +6: 15 + 6 = 21."},{"kind":"mcq","prompt":"The gaps grow by one each time. What comes next? 5, 6, 8, 11, 15, ?","options":["20","19","21","18"],"answer":0,"explain":"The gaps are +1, +2, +3, +4, so the next gap is +5: 15 + 5 = 20."}]},{"id":"pa3","title":"The Symbol Doors","icon":"🚪","kind":"lesson","story":"Three carved doors stand between you and the heart of the valley. Each door is decorated with a sequence of shapes, letters, or colours instead of numbers. The doors only open when you name the next symbol in line.","teach":[{"title":"Patterns Aren't Just Numbers","body":"Patterns can be made of letters, shapes, or colours too, not just numbers! The trick is the same: look at what changes from one item to the next, and use that same rule to guess what comes after.","visual":"🔺"}],"questions":[{"kind":"mcq","prompt":"What comes next? Star, Circle, Star, Circle, Star, ___","options":["Circle","Square","Star","Triangle"],"answer":0,"explain":"The pattern alternates Star and Circle, so after Star comes Circle."},{"kind":"mcq","prompt":"These letters skip one letter each time. What comes next? A, C, E, G, ___","options":["J","I","F","H"],"answer":1,"explain":"Each letter skips one: A(skip B) C(skip D) E(skip F) G(skip H) I."},{"kind":"mcq","prompt":"What comes next? Red, Red, Blue, Red, Red, Blue, Red, Red, ___","options":["Red","Green","Yellow","Blue"],"answer":3,"explain":"The pattern repeats in blocks of 'Red, Red, Blue', so after two Reds comes Blue."},{"kind":"numeric","prompt":"A row of shapes has 3 corners, then 4 corners, then 5 corners, then 6 corners. How many corners will the next shape have?","answer":7,"explain":"The number of corners increases by 1 each time, so 6 + 1 = 7."}]},{"id":"pa4","title":"The Imposter Hunt","icon":"🕵️","kind":"lesson","story":"A mischievous sprite has hidden one fake item inside every group of true pattern-followers. Look closely at each group, find the rule that most items follow, and catch the one item that breaks it!","teach":[{"title":"Finding the Odd One Out","body":"To find the odd one out, first figure out the rule that almost everything in the group follows — like 'all even numbers' or 'all multiples of 10'. The one item that breaks that rule is the odd one out!","visual":"🔍"}],"questions":[{"kind":"mcq","prompt":"Which number does not belong? 2, 4, 6, 9, 8","options":["9","2","8","4"],"answer":0,"explain":"All the other numbers are even, but 9 is odd."},{"kind":"mcq","prompt":"Which animal does not belong? Dog, Cat, Sparrow, Rabbit","options":["Sparrow","Rabbit","Cat","Dog"],"answer":0,"explain":"Dog, Cat, and Rabbit are mammals, but a Sparrow is a bird."},{"kind":"mcq","prompt":"Which number does not belong? 10, 20, 30, 45, 40","options":["40","10","45","20"],"answer":2,"explain":"All the other numbers are multiples of 10, but 45 is not."},{"kind":"mcq","prompt":"Which shape does not belong? Square, Cube, Circle, Triangle","options":["Cube","Square","Triangle","Circle"],"answer":0,"explain":"Square, Circle, and Triangle are flat 2D shapes, but a Cube is a solid 3D shape."},{"kind":"numeric","prompt":"Which number breaks this pattern: 5, 10, 15, 21, 25? Type the number that does not belong.","answer":21,"explain":"All the other numbers are multiples of 5, but 21 is not."}]},{"id":"pa5","title":"The Repeating Dance","icon":"💃","kind":"lesson","story":"The valley's guardian spirits perform an endless dance with a short set of moves that repeats over and over. To pass, you must predict a move or count moves far ahead in the routine, without watching the whole thing!","teach":[{"title":"Repeating Blocks","body":"A repeating pattern has a small 'block' that copies itself again and again, like Clap-Clap-Stomp, Clap-Clap-Stomp. To find a faraway position, count forward in blocks instead of one step at a time — it's much faster!","visual":"🔂"}],"questions":[{"kind":"mcq","prompt":"The dance repeats 'Clap, Clap, Stomp' again and again. What is the 8th action?","options":["Stomp","Jump","Clap","Clap Clap"],"answer":2,"explain":"Each block of 3 is Clap, Clap, Stomp. Position 8 is the 2nd move of the 3rd block, which is Clap."},{"kind":"mcq","prompt":"A bead pattern repeats 'Red, Yellow, Yellow, Green' again and again. What colour is the 10th bead?","options":["Yellow","Blue","Green","Red"],"answer":0,"explain":"Each block of 4 is Red, Yellow, Yellow, Green. Position 10 is the 2nd move of the 3rd block, which is Yellow."},{"kind":"numeric","prompt":"A necklace repeats 'Blue, Blue, Red' again and again. How many Red beads are in the first 12 beads?","answer":4,"explain":"Each block of 3 has exactly 1 Red bead. There are 12 / 3 = 4 blocks, so 4 Red beads."},{"kind":"numeric","prompt":"The pattern '1, 2, 3' repeats again and again: 1,2,3,1,2,3,... What is the 20th number?","answer":2,"explain":"Each block has 3 numbers. 18 is the end of the 6th block, so position 19 is 1 and position 20 is 2."}]},{"id":"pa6","title":"The Fortune Teller's Riddles","icon":"🔮","kind":"lesson","story":"At the last gate before Muddle's lair, a wise fortune teller tests whether you can use patterns to predict real things, not just numbers on stones. Answer her riddles about days, rows, and lines of friends to earn passage.","teach":[{"title":"Patterns Help Us Predict","body":"Patterns show up everywhere in real life — the days of the week repeat, seats in a row can follow a pattern, and even where people stand in a line can follow a rule. Spotting the pattern helps you predict what happens next.","visual":"🗓️"}],"questions":[{"kind":"numeric","prompt":"If Monday is day 1 and the days repeat every 7 days, on which day number does Monday happen again?","answer":8,"explain":"The week repeats every 7 days, so the next Monday is day 1 + 7 = day 8."},{"kind":"mcq","prompt":"Meena lines up pots in a repeating pattern: Big, Small, Small, Big, Small, Small, ... What is the 7th pot?","options":["Big","Small","Tiny","Medium"],"answer":0,"explain":"Each block of 3 is Big, Small, Small. Position 7 is the 1st move of the 3rd block, which is Big."},{"kind":"numeric","prompt":"Chairs are numbered 1 to 10. Ravi sits only on chairs with even numbers. How many chairs does Ravi use?","answer":5,"explain":"The even numbers from 1 to 10 are 2, 4, 6, 8, 10 — that's 5 chairs."},{"kind":"mcq","prompt":"Four friends stand in a line. C is first. B is right behind A. D is right behind B. Who is standing last?","options":["B","D","A","C"],"answer":1,"explain":"The order must be C, A, B, D, so D is standing last."},{"kind":"numeric","prompt":"A path has a stone on every even-numbered step from step 1 to step 20. How many stones are there in total?","answer":10,"explain":"The even steps are 2, 4, 6, ..., 20, which is 10 steps in total."}]},{"id":"pa-boss","title":"Muddle's Scrambled Lair","icon":"🎭","kind":"boss","story":"You finally reach Muddle the Pattern Thief, who has scrambled every pattern in the valley just to confuse you. Only by solving one final riddle from every kind of pattern you've learned can you restore order and win back Pattern Valley!","boss":{"name":"Muddle the Pattern Thief","taunt":"Numbers, letters, dances, doubles — I scrambled them ALL! Bet you can't put a single one back together!"},"teach":[],"questions":[{"kind":"numeric","prompt":"Find the missing number: 3, 7, 11, 15, ?","answer":19,"explain":"The rule is 'add 4' each time, so 15 + 4 = 19."},{"kind":"numeric","prompt":"These are square numbers. Find the missing number: 1, 4, 9, 16, 25, ?","answer":36,"explain":"These are 1x1, 2x2, 3x3, 4x4, 5x5, so next is 6x6 = 36."},{"kind":"mcq","prompt":"These letters skip one letter each time. What comes next? B, D, F, H, ?","options":["K","J","G","I"],"answer":1,"explain":"Each letter skips one: B(skip C) D(skip E) F(skip G) H(skip I) J."},{"kind":"mcq","prompt":"Which number does not belong? 12, 18, 24, 29, 30","options":["24","12","18","29"],"answer":3,"explain":"All the other numbers are multiples of 6, but 29 is not."},{"kind":"numeric","prompt":"A dance repeats 'Clap, Stomp, Stomp' again and again. How many Stomps happen in the first 15 actions?","answer":10,"explain":"Each block of 3 has 2 Stomps. There are 15 / 3 = 5 blocks, so 5 x 2 = 10 Stomps."},{"kind":"mcq","prompt":"Five stones are laid in a row: Red, Blue, Red, Blue, Red. What colour is the middle (3rd) stone?","options":["Blue","Red","Yellow","Green"],"answer":1,"explain":"The stones alternate Red, Blue, Red, Blue, Red, so the 3rd stone is Red."},{"kind":"numeric","prompt":"These are the 'staircase of dots' numbers. Find the missing number: 1, 3, 6, 10, 15, ?","answer":21,"explain":"The gaps grow by one each time: +2, +3, +4, +5, +6, so 15 + 6 = 21."}]}]},{"id":"thousandsaroundus4","index":3,"name":"Thousands Around Us","subtitle":"Computational Thinking — Chapter 4","emoji":"🔢","palette":{"from":"#fb923c","to":"#7c2d12"},"lessons":[{"id":"ta1","title":"The Digit Kingdom","icon":"🏰","kind":"lesson","story":"You land in a kingdom built entirely of number towers! Each tower has 4 floors, and the gate guard says only someone who understands place value may pass.","teach":[{"title":"Place Value Towers","body":"A 4-digit number has 4 places: Thousands, Hundreds, Tens and Ones. Each place is worth ten times more than the place to its right.","visual":"🏰"},{"title":"Reading the digits","body":"In 3452, the digit 3 is in the Thousands place (worth 3000), 4 is in Hundreds (400), 5 is in Tens (50), and 2 is in Ones (2).","visual":"🔢"}],"questions":[{"kind":"mcq","prompt":"In the number 4,728, which digit is in the Hundreds place?","options":["8","2","4","7"],"answer":3,"explain":"Reading from the left, 4 is Thousands, 7 is Hundreds, 2 is Tens, 8 is Ones."},{"kind":"numeric","prompt":"What is the value of the digit 5 in the number 5,639?","answer":5000,"explain":"5 is in the Thousands place, so it is worth 5000."},{"kind":"numeric","prompt":"What is the value of the digit 3 in the number 8,371?","answer":300,"explain":"3 is in the Hundreds place, so it is worth 300."},{"kind":"mcq","prompt":"Which of these numbers has a 9 in the Thousands place?","options":["9245","3409","1092","5920"],"answer":0,"explain":"9245 starts with 9, so 9 is in the Thousands place."}]},{"id":"ta2","title":"The Comparing Bridge","icon":"⚖️","kind":"lesson","story":"A rope bridge only lowers for the bigger number! Learn the computer's trick for comparing numbers - checking digits from left to right.","teach":[{"title":"Compare from the left","body":"To compare two numbers, look at the leftmost digit first. Whichever number has the bigger leftmost digit is the bigger number.","visual":"👈"},{"title":"Same digit? Keep going","body":"If the leftmost digits are equal, move one step right and compare the next digit. Keep going until you find digits that are different.","visual":"👉"}],"questions":[{"kind":"mcq","prompt":"Which number is bigger: 4,582 or 4,519?","options":["Cannot tell","4519","They are equal","4582"],"answer":3,"explain":"Thousands and Hundreds match (4 and 5), but Tens: 8 is bigger than 1, so 4582 wins."},{"kind":"mcq","prompt":"Which sign belongs in the blank: 3,721 ___ 3,699?","options":[">","<","cannot tell","="],"answer":0,"explain":"Thousands match (3), but Hundreds: 7 is bigger than 6, so 3721 is greater."},{"kind":"mcq","prompt":"Which of these four numbers is the SMALLEST: 6045, 6054, 6450, 6405?","options":["6045","6450","6054","6405"],"answer":0,"explain":"All start with 60, but 6045 has the smallest Tens digit (4), making it the smallest."},{"kind":"numeric","prompt":"Compare 2,983 and 2,938. Type the smaller of the two numbers.","answer":2938,"explain":"Thousands and Hundreds match (2 and 9), but Tens: 3 is smaller than 8, so 2938 is smaller."}]},{"id":"ta3","title":"The Digit Factory","icon":"🏭","kind":"lesson","story":"The Digit Factory hands you a pile of number tiles and a jammed machine. Arrange the tiles the right way to build the biggest or smallest number before the gears freeze!","teach":[{"title":"Building the biggest number","body":"To make the biggest number from a set of digits, place the largest digit first, then the next largest, and so on.","visual":"📈"},{"title":"Building the smallest number","body":"To make the smallest number, place the smallest digit first, then the rest in increasing order. If the smallest digit is 0, put the next-smallest digit first instead, so the number doesn't start with 0.","visual":"📉"}],"questions":[{"kind":"numeric","prompt":"Using the digits 7, 2, 9, 4 (each once), what is the LARGEST 4-digit number you can make?","answer":9742,"explain":"Arrange digits from biggest to smallest: 9, 7, 4, 2 gives 9742."},{"kind":"numeric","prompt":"Using the digits 7, 2, 9, 4 (each once), what is the SMALLEST 4-digit number you can make?","answer":2479,"explain":"Arrange digits from smallest to biggest: 2, 4, 7, 9 gives 2479."},{"kind":"numeric","prompt":"Using the digits 0, 5, 3, 8 (each once, no leading zero), what is the SMALLEST 4-digit number you can make?","answer":3058,"explain":"0 can't start the number, so the next-smallest digit 3 goes first, then the rest in order: 3, 0, 5, 8."},{"kind":"numeric","prompt":"You have seven digit tiles: 2, 9, 6, 4, 8, 1, 7. Pick 4 tiles to build the LARGEST 4-digit number (9876) and 4 tiles to build the SMALLEST 4-digit number (1246). Which single digit is used in BOTH numbers?","answer":6,"explain":"Largest uses 9,8,7,6 and smallest uses 1,2,4,6. The digit 6 appears in both groups."}]},{"id":"ta4","title":"Sorting Network Gate","icon":"🔀","kind":"lesson","story":"Two robot guards block the gate with comparison boxes. Feed them numbers, and each box sends the smaller one left and the bigger one right - just like a real computer sorting network!","teach":[{"title":"Compare and swap","body":"At each comparison box, the computer looks at two numbers at once. It sends the smaller number one way and the bigger number the other way.","visual":"🔀"},{"title":"Step by step","body":"Sorting doesn't happen all at once. It happens in tiny steps - comparing just two numbers at a time - until the whole list ends up in order.","visual":"🪜"}],"questions":[{"kind":"mcq","prompt":"45 and 28 enter a comparison box. The RULE is: smaller number follows the BLUE path. Which number follows blue?","options":["28","45","Both follow blue","Neither"],"answer":0,"explain":"28 is smaller than 45, so 28 follows the blue path."},{"kind":"mcq","prompt":"63 and 91 enter a comparison box with the same rule (smaller = blue). Which number follows the ORANGE (bigger) path?","options":["91","63","Both follow orange","Neither"],"answer":0,"explain":"91 is bigger than 63, so 91 follows the orange path."},{"kind":"numeric","prompt":"Four numbers enter two separate boxes: Box 1 compares 8 and 3. Box 2 compares 6 and 1. Using the rule smaller = blue, which number follows the blue path out of Box 1?","answer":3,"explain":"3 is smaller than 8, so 3 follows blue out of Box 1."},{"kind":"mcq","prompt":"Now the rule is REVERSED: the BIGGER number follows blue, and the smaller follows orange. With inputs 52 and 19, which number now follows blue?","answer":0,"options":["52","19","Both","Neither"],"explain":"With the reversed rule, the bigger number (52) follows blue."},{"kind":"mcq","prompt":"If every comparison box in a sorting network has its rule reversed (bigger goes where smaller used to go), what happens to the final sorted output?","options":["It comes out in reverse order (biggest to smallest)","It stays exactly the same","Nothing can be said about it","It depends on the input order"],"answer":0,"explain":"Reversing every comparison flips the whole sort, so numbers come out from biggest to smallest."}]},{"id":"ta5","title":"Bubble Sort Trail","icon":"🫧","kind":"lesson","story":"Walk the Bubble Sort Trail! At each stepping stone, compare two neighbours - if the left number is bigger than the right, swap them - and keep walking until the trail is sorted.","teach":[{"title":"The bubble sort idea","body":"Bubble sort compares each pair of neighbouring numbers, left to right. If the left number is bigger than the right number, they swap places.","visual":"🫧"},{"title":"One pass at a time","body":"After one full pass through the list, the biggest number always 'bubbles' all the way to the last position. Then you do another pass for the rest.","visual":"🔁"}],"questions":[{"kind":"mcq","prompt":"Look at the list 5, 2, 8, 1. Compare the first pair (5 and 2). Since 5 is bigger than 2, swap them. What does the list look like now?","options":["5, 2, 1, 8","2, 5, 8, 1","2, 8, 5, 1","5, 2, 8, 1"],"answer":1,"explain":"Swapping 5 and 2 gives 2, 5, 8, 1 - the rest of the list stays the same for now."},{"kind":"mcq","prompt":"Continuing on 2, 5, 8, 1: compare the next pair (5 and 8) - no swap needed since 5 is smaller. Now compare (8 and 1). Since 8 is bigger than 1, swap them. What is the list now?","options":["1, 5, 8, 2","2, 8, 5, 1","2, 5, 1, 8","2, 5, 8, 1"],"answer":2,"explain":"Swapping 8 and 1 gives 2, 5, 1, 8."},{"kind":"numeric","prompt":"That was one full pass over the list 5, 2, 8, 1, ending in 2, 5, 1, 8. Which number 'bubbled' all the way to the last position?","answer":8,"explain":"The biggest number, 8, always ends up at the end after one full pass."},{"kind":"mcq","prompt":"Starting fresh with the list 9, 4, 6, 2 - after ONE full bubble sort pass (compare and swap neighbours left to right), what is the list?","options":["4, 6, 2, 9","9, 4, 6, 2","4, 9, 6, 2","2, 4, 6, 9"],"answer":0,"explain":"Step by step: swap(9,4)->4,9,6,2; swap(9,6)->4,6,9,2; swap(9,2)->4,6,2,9."},{"kind":"numeric","prompt":"In that same pass over 9, 4, 6, 2, how many swaps happened in total?","answer":3,"explain":"9 was swapped with 4, then with 6, then with 2 - three swaps in all."}]},{"id":"ta6","title":"Mystery Digit Detective","icon":"🕵️","kind":"lesson","story":"A trickster has hidden digits behind mystery letters! Put on your detective hat and use place value clues to figure out what MUST be true, even without knowing the secret digit.","teach":[{"title":"Unknown digits","body":"Sometimes a letter like A or B stands for a hidden digit inside a number. You can still figure out facts about the number by comparing the digits you DO know.","visual":"🕵️"},{"title":"Compare position by position","body":"When two numbers share the same hidden letter in the same place, look at a different place where the digits are already known to decide which number is bigger.","visual":"🔍"}],"questions":[{"kind":"mcq","prompt":"The numbers 4B27 and 4B95 both use the SAME hidden digit B, in the same Hundreds spot. Which statement is always true, no matter what digit B is?","options":["4B27 is always smaller than 4B95","4B27 is always bigger than 4B95","Cannot tell without knowing B","They are always equal"],"answer":0,"explain":"Thousands (4) and Hundreds (B) match, but Tens: 2 is less than 9, so 4B27 is always smaller."},{"kind":"numeric","prompt":"The number 3X56 has a hidden digit X in the Hundreds place. What is the LARGEST value this number could be?","answer":3956,"explain":"The biggest digit X could be is 9, giving 3956."},{"kind":"numeric","prompt":"The number 3X56 has a hidden digit X in the Hundreds place. What is the SMALLEST value this number could be?","answer":3056,"explain":"The smallest digit X could be is 0, giving 3056."},{"kind":"numeric","prompt":"In the number 4,256 the Tens digit and the Thousands digit swap places. What is the new number?","answer":5246,"explain":"Thousands (4) and Tens (5) swap, so the number becomes 5,246."},{"kind":"numeric","prompt":"Add the Hundreds digit of 3,482 to the Hundreds digit of 5,196. What is the sum?","answer":5,"explain":"The Hundreds digit of 3482 is 4, and of 5196 is 1. 4 + 1 = 5."}]},{"id":"ta-boss","title":"Chaos, the Great Unsorter","icon":"🌪️","kind":"boss","story":"At the top of the number kingdom waits Chaos, the Great Unsorter - a swirling storm that scrambles every list it touches. Only a true master of place value and sorting can calm the storm!","boss":{"name":"Chaos, the Great Unsorter","taunt":"Numbers are much more fun all mixed up - let's see if you can out-sort me!"},"teach":[{"title":"Everything you've learned","body":"Place value tells you what each digit is worth. Comparing digit by digit tells you which number is bigger. Sorting networks and bubble sort put whole lists in order, one comparison at a time.","visual":"🧭"}],"questions":[{"kind":"numeric","prompt":"What is the value of the digit 8 in the number 8,204?","answer":8000,"explain":"8 is in the Thousands place, so it is worth 8000."},{"kind":"mcq","prompt":"Which number is bigger: 7,102 or 7,120?","options":["Cannot tell","They are equal","7102","7120"],"answer":3,"explain":"Thousands and Hundreds match, but Tens: 2 is bigger than 0, so 7120 wins."},{"kind":"numeric","prompt":"Using the digits 5, 0, 2, 9 (each once, no leading zero), what is the SMALLEST 4-digit number you can make?","answer":2059,"explain":"0 can't start the number, so 2 goes first, then the rest in order: 2, 0, 5, 9."},{"kind":"mcq","prompt":"73 and 47 enter a comparison box where the BIGGER number follows the orange path. Which number follows orange?","options":["73","47","Both","Neither"],"answer":0,"explain":"73 is bigger than 47, so 73 follows the orange path."},{"kind":"mcq","prompt":"Using bubble sort, after ONE full pass over the list 9, 3, 6, 2 (compare and swap neighbours left to right), what is the list?","options":["2, 3, 6, 9","3, 6, 2, 9","3, 9, 6, 2","9, 3, 6, 2"],"answer":1,"explain":"Step by step: swap(9,3)->3,9,6,2; swap(9,6)->3,6,9,2; swap(9,2)->3,6,2,9."},{"kind":"numeric","prompt":"The Hundreds digit of 6,732 is 7, and the Hundreds digit of 2,891 is 8. What is 7 + 8?","answer":15,"explain":"7 + 8 = 15."},{"kind":"mcq","prompt":"Which sentence best describes how a sorting network puts numbers in order?","options":["It asks a teacher for the answer","It guesses the order randomly","It compares two numbers at a time and sends the smaller one one way, the bigger one the other way","It only works if the numbers are already close to sorted"],"answer":2,"explain":"A sorting network is built from simple compare-and-swap steps repeated many times."}]}]},{"id":"sharingmeasuring4","index":4,"name":"Sharing and Measuring","subtitle":"Computational Thinking — Chapter 5","emoji":"⚖️","palette":{"from":"#facc15","to":"#713f12"},"lessons":[{"id":"sm1","title":"Fair Shares for Friends","icon":"🍬","kind":"lesson","story":"The Candy Cart has rolled into town, but the cart's wheel only turns if every basket is shared out perfectly equally. Help the twins divide their treasures fairly before the cart squeaks away!","teach":[{"title":"Sharing equally","body":"When we share a group of things equally, everyone gets the SAME amount. To find each share, we divide the total number of things by the number of people sharing.","visual":"🍬"},{"title":"Leftovers happen!","body":"Sometimes a total cannot be split perfectly — a few items are left over after everyone gets an equal share. These leftovers are called the remainder.","visual":"➗"}],"questions":[{"kind":"numeric","prompt":"Riya shares 18 marbles equally among herself and 2 friends (3 children in all). How many marbles does each child get?","answer":6,"explain":"18 marbles shared among 3 children: 18 ÷ 3 = 6 marbles each."},{"kind":"numeric","prompt":"24 stickers are shared equally among 4 kids. How many stickers does each kid get?","answer":6,"explain":"24 ÷ 4 = 6 stickers per kid."},{"kind":"numeric","prompt":"17 pencils are shared as equally as possible among 5 friends. How many pencils are left over once every friend has the same number?","answer":2,"explain":"5 × 3 = 15, and 17 − 15 = 2 pencils are left over as the remainder."},{"kind":"mcq","prompt":"Priya has some chocolates that she wants to share equally among 4 friends with none left over. Which of these amounts CANNOT be shared exactly?","options":["12","16","14","20"],"answer":2,"explain":"12, 16, and 20 all divide exactly by 4, but 14 ÷ 4 leaves a remainder of 2."}]},{"id":"sm2","title":"Splitting the Big Job","icon":"🧩","kind":"lesson","story":"The Great Library has 40 books scattered on the floor before opening time, and the clock is ticking! Break the giant job into smaller equal jobs so the whole team can finish together.","teach":[{"title":"Decomposition: breaking big jobs into small ones","body":"A big, messy job can feel impossible alone. Computational thinkers break it into smaller, equal-sized jobs that are easy to finish. This is called decomposition.","visual":"🧩"},{"title":"Sharing chores fairly","body":"When friends split a big job into equal smaller jobs, each person knows exactly what to do, and the work gets done faster and more fairly.","visual":"🧹"}],"questions":[{"kind":"mcq","prompt":"Aarav must sort 40 books before the library opens. He breaks the job into 4 equal smaller jobs and asks 3 friends to help. What computational thinking skill is Aarav using?","options":["Decomposition","Guessing","Debugging","Pattern recognition"],"answer":0,"explain":"Breaking one big job into smaller, equal jobs is called decomposition."},{"kind":"numeric","prompt":"40 books are split into 4 equal jobs. How many books are in each job?","answer":10,"explain":"40 ÷ 4 = 10 books per job."},{"kind":"numeric","prompt":"A mural wall of 36 tiles needs cleaning. 6 friends work in equal turns. How many tiles does each friend clean?","answer":6,"explain":"36 ÷ 6 = 6 tiles for each friend."},{"kind":"numeric","prompt":"A class of 28 students is decorating the hall. The teacher breaks the job into 7 equal smaller teams. How many students are in each team?","answer":4,"explain":"28 ÷ 7 = 4 students per team."}]},{"id":"sm3","title":"Full, Half, or Empty?","icon":"🧃","kind":"lesson","story":"The Juice Bar's shelf is lined with bottles marked with measuring lines, but the labels have washed off! Read the water levels carefully and figure out how full each bottle really is.","teach":[{"title":"Estimating how full something is","body":"Containers often have marks from empty (0) to full (the top mark). If the liquid reaches past the halfway mark, the container is more than half full; if it's before the halfway mark, it's less than half full.","visual":"🧃"},{"title":"Comparing fill levels","body":"To compare two same-size containers, just compare their marks — the one with the higher mark has more liquid in it.","visual":"📏"}],"questions":[{"kind":"mcq","prompt":"A bottle has 10 equal marks from bottom (empty) to top (full). The water level is at mark 3. About how full is the bottle?","options":["More than half full","Completely full","Less than half full","Exactly half full"],"answer":2,"explain":"Mark 3 out of 10 is less than mark 5, which is the halfway point, so the bottle is less than half full."},{"kind":"mcq","prompt":"Five bottles each have marks from 0 (empty) to 10 (full). Their water levels are: Bottle A = 2, Bottle B = 6, Bottle C = 4, Bottle D = 8, Bottle E = 1. How many bottles are filled to LESS than half their capacity?","options":["3","5","2","4"],"answer":0,"explain":"Less than half means less than mark 5. Bottles A (2), C (4), and E (1) qualify — that's 3 bottles."},{"kind":"numeric","prompt":"A jug holds 8 cups of juice when full. It is currently filled to the 5-cup mark. How many more cups are needed to fill it completely?","answer":3,"explain":"8 − 5 = 3 more cups are needed to fill the jug."},{"kind":"mcq","prompt":"Glass X is filled to the 6-out-of-10 mark. Glass Y is filled to the 4-out-of-10 mark. Which glass has more liquid?","options":["Glass X","Glass Y","Both equal","Cannot tell"],"answer":0,"explain":"Mark 6 is higher than mark 4, so Glass X has more liquid."}]},{"id":"sm4","title":"Who Has More? Comparing and Ordering","icon":"🔎","kind":"lesson","story":"Three mysterious jars sit on the wizard's shelf with no labels, only whispered clues about which holds more. Use your deduction skills to line them up from least to most!","teach":[{"title":"Comparing without a ruler","body":"Sometimes we don't have exact numbers, only clues like 'more than' or 'less than'. We can still figure out the correct order by connecting the clues together, one step at a time.","visual":"🔎"},{"title":"Using clues to solve a mystery","body":"A good computational thinker lines up every clue carefully before deciding on an answer, instead of guessing.","visual":"🧠"}],"questions":[{"kind":"mcq","prompt":"Meera has more juice than Karan. Karan has more juice than Sofia. Who has the LEAST juice?","options":["Meera","Karan","Cannot tell","Sofia"],"answer":3,"explain":"The order from most to least is Meera, then Karan, then Sofia — so Sofia has the least."},{"kind":"mcq","prompt":"Jar 1 holds less water than Jar 2. Jar 3 holds more water than Jar 2. Which jar holds the MOST water?","options":["Jar 2","Jar 3","Jar 1","Cannot tell"],"answer":1,"explain":"Jar 3 is more than Jar 2, and Jar 2 is more than Jar 1, so Jar 3 has the most water."},{"kind":"numeric","prompt":"Amit has twice as much lemonade as Priya. Priya has 3 cups. How many cups does Amit have?","answer":6,"explain":"Twice as much as 3 cups is 3 × 2 = 6 cups."},{"kind":"mcq","prompt":"Four cups of lemonade all hold different amounts. Cup A has more than Cup B. Cup C has more than Cup A. Cup D has less than Cup B. Which cup has the LEAST lemonade?","options":["Cup D","Cup B","Cup C","Cup A"],"answer":0,"explain":"Putting the clues together: D < B < A < C, so Cup D has the least lemonade."}]},{"id":"sm5","title":"The Leftover Puzzle","icon":"🍎","kind":"lesson","story":"The Orchard Festival needs every basket packed with the exact same number of apples, but the harvest numbers keep leaving odd amounts behind. Hunt down the leftovers!","teach":[{"title":"When sharing doesn't come out even","body":"Not every total can be split perfectly among a group. When it can't, the extra items that don't fit into an equal share are called the leftover, or remainder.","visual":"🍎"},{"title":"Spotting numbers that share evenly","body":"A number shares evenly among a group only if dividing it by the group size leaves nothing over. Checking this quickly helps us plan fair sharing before we even start.","visual":"✅"}],"questions":[{"kind":"numeric","prompt":"23 candies are shared as equally as possible among 5 children. How many candies are left over?","answer":3,"explain":"5 × 4 = 20, and 23 − 20 = 3 candies are left over."},{"kind":"mcq","prompt":"Which of these numbers of stickers can be shared EXACTLY equally among 6 friends, with none left over?","options":["35","28","30","32"],"answer":2,"explain":"30 ÷ 6 = 5 exactly. 28, 32, and 35 all leave a remainder when divided by 6."},{"kind":"numeric","prompt":"35 apples are packed exactly equally into 5 baskets, with none left over. How many apples are in each basket?","answer":7,"explain":"35 ÷ 5 = 7 apples in each basket."},{"kind":"mcq","prompt":"Which of these numbers of buttons CANNOT be split into 3 equal groups with none left over?","options":["27","21","20","18"],"answer":2,"explain":"18, 21, and 27 all divide exactly by 3, but 20 ÷ 3 leaves a remainder of 2."}]},{"id":"sm6","title":"Container Detective","icon":"🕵️","kind":"lesson","story":"The Measuring Lab has run out of labelled cups, and the head scientist needs an exact 2 litres for tonight's experiment. Only careful, step-by-step thinking will save the day.","teach":[{"title":"Solving it step by step","body":"When you break a tricky problem into clear, ordered steps, it becomes much easier to solve. This step-by-step plan is called an algorithm.","visual":"🪜"},{"title":"Being a measurement detective","body":"Instead of guessing amounts, a good detective compares things fairly — using the same size cup, or careful marks — before deciding which is more.","visual":"🕵️"}],"questions":[{"kind":"mcq","prompt":"You want to know which of three bottles (X, Y, Z) has the most water, but you cannot see inside them. What is the BEST first step?","options":["Ask a friend to guess for you","Guess by looking at the bottle's colour","Pour each bottle into the same-size measuring cup and compare","Weigh the empty bottles"],"answer":2,"explain":"Pouring each into an identical measuring cup lets you compare the levels fairly."},{"kind":"numeric","prompt":"You have a full 5-litre jug and an empty 3-litre jug. You pour water from the 5-litre jug into the 3-litre jug until the 3-litre jug is completely full. How many litres are left in the 5-litre jug?","answer":2,"explain":"5 − 3 = 2 litres remain in the 5-litre jug."},{"kind":"mcq","prompt":"A recipe needs exactly 4 cups of milk, but you only have a 1-cup measuring cup. What should you do?","options":["Use a bigger cup and estimate half","Ask someone else to measure it by eye","Fill the 1-cup measure and pour it in 4 times","Guess when the bowl looks full"],"answer":2,"explain":"Repeating a known, exact step (filling the 1-cup measure) 4 times gives exactly 4 cups — a simple algorithm."},{"kind":"numeric","prompt":"Bottle P is filled to the 7-mark out of 10. Bottle Q is filled to the 4-mark out of 10. How many more marks of water does Bottle P have than Bottle Q?","answer":3,"explain":"7 − 4 = 3 marks more water in Bottle P."}]},{"id":"sm-boss","title":"The Grand Sharing Challenge","icon":"🏆","kind":"boss","boss":{"name":"Baron Unfair","taunt":"Ha! Nobody can split my treasure evenly... or measure my secret potions. Prove me wrong, if you dare!"},"story":"Baron Unfair has locked away the town's treasure behind puzzles of sharing and measuring. Solve every challenge to prove that fair shares and careful measuring always win!","teach":[],"questions":[{"kind":"numeric","prompt":"28 story-books are shared equally among 4 reading corners. How many books go to each corner?","answer":7,"explain":"28 ÷ 4 = 7 books per reading corner."},{"kind":"mcq","prompt":"Which of these numbers of sweets CANNOT be shared exactly equally among 5 friends?","options":["25","20","22","30"],"answer":2,"explain":"20, 25, and 30 all divide exactly by 5, but 22 ÷ 5 leaves a remainder of 2."},{"kind":"mcq","prompt":"Tank A is filled to the 8-mark out of 10. Tank B is filled to the 3-mark out of 10. Which tank is LESS than half full?","options":["Tank B","Tank A","Both tanks","Neither tank"],"answer":0,"explain":"Mark 3 is below the halfway mark of 5, so Tank B is less than half full."},{"kind":"numeric","prompt":"A juice bottle holds 12 cups when full. It is filled to the 5-cup mark. How many more cups are needed to fill it completely?","answer":7,"explain":"12 − 5 = 7 more cups are needed."},{"kind":"mcq","prompt":"Priya has more mangoes than Dev. Dev has more mangoes than Anu. Who has the MOST mangoes?","options":["Dev","Anu","Priya","Cannot tell"],"answer":2,"explain":"The order from most to least is Priya, then Dev, then Anu, so Priya has the most."},{"kind":"mcq","prompt":"Kabir breaks the job of watering 30 plants into 5 equal smaller jobs so he can finish faster with friends. What computational thinking skill is this?","options":["Debugging","Abstraction","Pattern recognition","Decomposition"],"answer":3,"explain":"Splitting one big job into smaller, equal jobs is decomposition."},{"kind":"numeric","prompt":"You have a full 7-litre jug of water. You pour it into an empty 4-litre jug until the 4-litre jug is completely full. How many litres remain in the 7-litre jug?","answer":3,"explain":"7 − 4 = 3 litres remain in the 7-litre jug."}]}]},{"id":"measuringlength4","index":5,"name":"Measuring Length","subtitle":"Computational Thinking — Chapter 6","emoji":"📏","palette":{"from":"#4ade80","to":"#14532d"},"lessons":[{"id":"ml1","title":"The Hidden Ribbon","icon":"🎀","kind":"lesson","story":"Deep in a dusty ruin you find a magic ribbon marked off into equal squares — but shadows and rubble cover parts of it. The vault door only opens if you can work out exactly how many squares are hidden.","teach":[{"title":"Counting equal squares","body":"A ribbon or line can be marked off into many small equal squares called units. If you know the total number of squares and how many you can SEE, the hidden ones are just total minus visible.","visual":"📏"},{"title":"Hidden = Total − Visible","body":"When a block or curtain covers part of a line, count carefully from the starting square to the ending square of the cover to find exactly how many squares are hidden underneath it.","visual":"🧩"}],"questions":[{"kind":"numeric","prompt":"A ribbon is made of 20 equal small squares in a row. You can count 14 visible squares; the rest are hidden behind a rock. How many squares are hidden?","answer":6,"explain":"20 total squares minus 14 visible squares leaves 6 hidden squares."},{"kind":"numeric","prompt":"A rope is made of 30 equal beads. One rock covers 5 beads and another rock covers 7 beads. How many beads can you still see?","answer":18,"explain":"30 − 5 − 7 = 18 beads remain visible."},{"kind":"mcq","prompt":"Three ribbons X, Y and Z are each 20 squares long. Ribbon X has 9 squares hidden, Ribbon Y has 6 squares hidden, and Ribbon Z has 12 squares hidden. Which ribbon has the LONGEST hidden part?","options":["Ribbon Y","All are equal","Ribbon Z","Ribbon X"],"answer":2,"explain":"Ribbon Z has 12 hidden squares, more than Ribbon X's 9 or Ribbon Y's 6."},{"kind":"numeric","prompt":"A wall is built from 25 equal bricks in a row, numbered 1 to 25. A curtain hides bricks number 10 to 17 (both included). How many bricks are hidden behind the curtain?","answer":8,"explain":"From brick 10 to brick 17 is 17 − 10 + 1 = 8 bricks."}]},{"id":"ml2","title":"Which Line Is Longest?","icon":"⚖️","kind":"lesson","story":"A rope bridge across the canyon will only lower for the traveller who can order its strands from shortest to longest using nothing but clues whispered by the wind.","teach":[{"title":"Comparing without a ruler","body":"You can figure out the order of lengths just from clues like 'longer than' and 'shorter than'. If A is longer than B, and B is longer than C, then A must also be longer than C.","visual":"⚖️"},{"title":"Sorting into groups","body":"Sometimes a line has to be sorted into more than one group at once, such as 'longer than D' and 'shorter than B'. Check every clue carefully before deciding where a line belongs.","visual":"📊"}],"questions":[{"kind":"mcq","prompt":"Ribbon A is longer than Ribbon B. Ribbon B is longer than Ribbon C. Which ribbon is the SHORTEST?","options":["Ribbon A","Ribbon C","Cannot tell","Ribbon B"],"answer":1,"explain":"A > B > C, so C is the shortest of the three."},{"kind":"numeric","prompt":"Rope P is 45 cm long. Rope Q is 12 cm shorter than Rope P. How long is Rope Q, in cm?","answer":33,"explain":"45 − 12 = 33 cm."},{"kind":"mcq","prompt":"Five ropes are lined up from shortest to longest like this: Rope M, Rope N, Rope O, Rope P, Rope Q (M is shortest, Q is longest). Group 1 has ropes longer than Rope N. Group 2 has ropes longer than Rope O. Which rope belongs to Group 1 but NOT to Group 2?","options":["Rope N","Rope Q","Rope O","Rope P"],"answer":2,"explain":"Group 1 (longer than N) is O, P, Q. Group 2 (longer than O) is P, Q. Only Rope O is in Group 1 but not Group 2."},{"kind":"numeric","prompt":"Stick X is 18 cm long. Stick Y is twice as long as Stick X. How long is Stick Y, in cm?","answer":36,"explain":"Twice 18 cm is 18 × 2 = 36 cm."}]},{"id":"ml3","title":"Matching Heights","icon":"🌳","kind":"lesson","story":"The garden of hedges hides a secret gate that opens only when you spot the one hedge whose height matches no other, and work out which snail truly crawls the fastest.","teach":[{"title":"Same length, different look","body":"Two things can have exactly the same length even if they are described differently, as long as the numbers and units match. To find a match, compare each length to all the others.","visual":"📐"},{"title":"Length over time is speed","body":"If two things take the SAME amount of time but travel DIFFERENT lengths, the one that covers the longer length is moving faster.","visual":"🐌"}],"questions":[{"kind":"mcq","prompt":"Five garden hedges have these heights: Hedge A = 10 cm, Hedge B = 14 cm, Hedge C = 10 cm, Hedge D = 18 cm, Hedge E = 14 cm. Which hedge does NOT have any other hedge of the same height?","options":["Hedge C","Hedge B","Hedge D","Hedge A"],"answer":2,"explain":"10 cm and 14 cm each appear twice, but 18 cm (Hedge D) appears only once."},{"kind":"numeric","prompt":"Two fences have the same length. Fence 1 is built as 6 rows of 5 bricks each. Fence 2 is built as 3 rows of 10 bricks each. How many bricks long is each fence?","answer":30,"explain":"6 × 5 = 30 and 3 × 10 = 30, so both fences use 30 bricks."},{"kind":"numeric","prompt":"Four ribbons have lengths 22 cm, 35 cm, 22 cm and 22 cm. What is the length, in cm, of the ribbon that appears only once?","answer":35,"explain":"22 cm appears three times, but 35 cm appears only once."},{"kind":"mcq","prompt":"Three snails each take exactly 10 minutes to crawl to a leaf. Snail A's path is 40 cm long, Snail B's path is 25 cm long, and Snail C's path is 55 cm long. Which snail crawls the FASTEST?","options":["Snail C","All are equally fast","Snail A","Snail B"],"answer":0,"explain":"In the same 10 minutes, Snail C covers the greatest length (55 cm), so it is the fastest."}]},{"id":"ml4","title":"The Shrinking Wall","icon":"🧱","kind":"lesson","story":"The castle moat is guarded by a wall puzzle: only someone who understands perimeter — the full distance around a shape — can figure out how the fences change and cross safely.","teach":[{"title":"What is perimeter?","body":"Perimeter is the total length you would walk if you went all the way around the outside edge of a shape. For a rectangle, perimeter = 2 × (length + width).","visual":"🧱"},{"title":"Working backwards","body":"If you know the perimeter and one side of a rectangle, you can work out the missing side by first subtracting, then dividing, step by step.","visual":"➗"}],"questions":[{"kind":"numeric","prompt":"A rectangular garden is 12 m long and 7 m wide. What is its perimeter, in metres?","answer":38,"explain":"Perimeter = 2 × (12 + 7) = 2 × 19 = 38 m."},{"kind":"numeric","prompt":"A square playground has a perimeter of 32 m. How long is each side, in metres?","answer":8,"explain":"A square has 4 equal sides, so 32 ÷ 4 = 8 m per side."},{"kind":"mcq","prompt":"A rectangular field is fenced on all four sides. If the field's length is doubled but its width stays the same, what happens to the perimeter?","options":["It increases","It stays exactly the same","It decreases","It becomes zero"],"answer":0,"explain":"A longer side adds more distance to walk around, so the perimeter increases."},{"kind":"numeric","prompt":"A rectangle has a length of 15 cm and a perimeter of 50 cm. What is its width, in cm?","answer":10,"explain":"Half of 50 is 25, which is length + width. 25 − 15 = 10 cm width."}]},{"id":"ml5","title":"Unit Conversion Locks","icon":"🔐","kind":"lesson","story":"Every treasure chest in the vault has a lock that only opens for a length written in the RIGHT unit. Convert carefully between millimetres, centimetres and metres to claim the treasure.","teach":[{"title":"Small units, big units","body":"10 millimetres (mm) = 1 centimetre (cm), and 100 centimetres (cm) = 1 metre (m). To turn a bigger unit into a smaller one, multiply. To turn a smaller unit into a bigger one, divide.","visual":"📏"},{"title":"Step by step conversion","body":"For a mixed measurement like 3 m 25 cm, first change the metres into centimetres (3 × 100 = 300), then add the extra centimetres (300 + 25 = 325 cm).","visual":"🔢"}],"questions":[{"kind":"numeric","prompt":"How many centimetres are there in 4 metres?","answer":400,"explain":"4 × 100 = 400 cm."},{"kind":"numeric","prompt":"A ribbon is 2 m 30 cm long. What is its length in centimetres?","answer":230,"explain":"2 m = 200 cm, plus 30 cm = 230 cm."},{"kind":"numeric","prompt":"A pencil is 90 mm long. What is its length in centimetres?","answer":9,"explain":"10 mm = 1 cm, so 90 mm ÷ 10 = 9 cm."},{"kind":"mcq","prompt":"Which length is exactly the SAME as 5 metres?","options":["5,000 cm","500 cm","50 cm","5 cm"],"answer":1,"explain":"5 m × 100 = 500 cm."},{"kind":"numeric","prompt":"A blue rope is 1 m 40 cm long and a red rope is 60 cm long. What is the total length of both ropes, in centimetres?","answer":200,"explain":"1 m 40 cm = 140 cm. 140 + 60 = 200 cm."}]},{"id":"ml6","title":"The Ruler Detective","icon":"🔎","kind":"lesson","story":"Detective Mouse needs your help! Every clue at the crime scene is measured against a ruler whose zero mark is scratched away, so you must always subtract the starting mark from the ending mark.","teach":[{"title":"Reading a ruler correctly","body":"The length of an object equals its ENDING mark minus its STARTING mark — not just the ending number. This matters most when the object doesn't start exactly at the 0 mark.","visual":"📏"},{"title":"A worked example","body":"If a leaf's edge lines up with the 3 cm mark and its tip lines up with the 10 cm mark, its length is 10 − 3 = 7 cm, not 10 cm.","visual":"🍃"}],"questions":[{"kind":"numeric","prompt":"A leaf is placed on a ruler. Its left edge touches the 2 cm mark and its right edge touches the 9 cm mark. How long is the leaf, in cm?","answer":7,"explain":"9 − 2 = 7 cm."},{"kind":"numeric","prompt":"A key is measured against a ruler. It starts at the 5 cm mark and ends at the 13 cm mark. What is the length of the key, in cm?","answer":8,"explain":"13 − 5 = 8 cm."},{"kind":"mcq","prompt":"Which is the correct way to find the length of an object placed on a ruler?","options":["Ending mark minus Starting mark","Just read the starting mark","Just read the ending mark","Add the ending and starting marks"],"answer":0,"explain":"The true length is always the ending mark minus the starting mark, especially when the object does not begin at 0."},{"kind":"numeric","prompt":"A twig's left end is at the 4 cm mark and its right end is at the 15 cm mark. How long is the twig, in cm?","answer":11,"explain":"15 − 4 = 11 cm."},{"kind":"numeric","prompt":"Two pencils are measured on the same ruler. Pencil A goes from the 1 cm mark to the 12 cm mark. Pencil B goes from the 6 cm mark to the 14 cm mark. By how many cm is the longer pencil longer than the shorter one?","answer":3,"explain":"Pencil A is 12 − 1 = 11 cm. Pencil B is 14 − 6 = 8 cm. 11 − 8 = 3 cm."}]},{"id":"ml-boss","title":"Longa the Length Dragon","icon":"🏆","kind":"boss","boss":{"name":"Longa the Length Dragon","taunt":"Ha! Not even my own tail's length can save you if your measuring skills come up short!"},"story":"At the Exit Gate, Longa the Length Dragon coils around the last treasure and roars a final round of riddles — hidden segments, comparisons, perimeters, conversions and ruler tricks, all at once!","teach":[],"questions":[{"kind":"numeric","prompt":"A fence is made of 40 equal planks in a row, numbered 1 to 40. A big banner covers planks 12 to 25 (both included). How many planks are hidden behind the banner?","answer":14,"explain":"From plank 12 to plank 25 is 25 − 12 + 1 = 14 planks."},{"kind":"mcq","prompt":"Rope A is longer than Rope B. Rope B is longer than Rope C. Rope C is longer than Rope D. Which rope is the LONGEST?","options":["Rope A","Rope B","Rope D","Rope C"],"answer":0,"explain":"A > B > C > D, so Rope A is the longest."},{"kind":"numeric","prompt":"A rectangular dragon cage is 9 m long and 6 m wide. What is its perimeter, in metres?","answer":30,"explain":"Perimeter = 2 × (9 + 6) = 2 × 15 = 30 m."},{"kind":"numeric","prompt":"The dragon's tail is 3 m 45 cm long. What is the length of the tail in centimetres?","answer":345,"explain":"3 m = 300 cm, plus 45 cm = 345 cm."},{"kind":"numeric","prompt":"A sword is measured on a ruler. Its handle starts at the 2 cm mark and its tip ends at the 27 cm mark. How long is the sword, in cm?","answer":25,"explain":"27 − 2 = 25 cm."},{"kind":"mcq","prompt":"Five torches have these heights: 20 cm, 35 cm, 20 cm, 50 cm, 35 cm. Which height appears only ONCE?","options":["20 cm","35 cm","50 cm","30 cm"],"answer":2,"explain":"20 cm and 35 cm each appear twice, but 50 cm appears only once."},{"kind":"numeric","prompt":"A treasure map shows a path made of 60 equal steps, numbered 1 to 60. Shadows hide steps 18 through 33 (both included). How many steps are hidden in shadow?","answer":16,"explain":"From step 18 to step 33 is 33 − 18 + 1 = 16 steps."}]}]},{"id":"cleanestvillage4","index":6,"name":"The Cleanest Village","subtitle":"Computational Thinking — Chapter 7","emoji":"🏘️","palette":{"from":"#22d3ee","to":"#164e63"},"lessons":[{"id":"cv1","title":"The Spending Clues","icon":"🔍","kind":"lesson","story":"Raju and Meena are the first volunteers to reach Clean Street. Both started with the same pocket money, but only careful clues can tell you who spent more on their cleaning tools!","teach":[{"title":"Reading clues about money","body":"In these puzzles, you're told how two people's spending compares — like 'A spent Rs 30 more than B.' You use that clue, plus a total limit, to figure out exactly what could have happened. Read every clue carefully before deciding!","visual":"🔍"},{"title":"Highest possible vs lowest possible","body":"Sometimes many answers fit the clues, but the question asks for the highest or lowest possible amount. Try pushing the value as big (or as small) as the clues allow, then check it still fits every rule.","visual":"📈"}],"questions":[{"kind":"mcq","prompt":"Raju and Meena each started with Rs 150. Raju spent Rs 40 more than Meena on brooms. What is the HIGHEST possible amount Meena could have spent, if Raju cannot spend more than Rs 150?","options":["Rs 150","Rs 70","Rs 110","Rs 40"],"answer":2,"explain":"If Meena spent Rs 110, Raju spent Rs 110 + 40 = Rs 150, which is the most Raju can spend. So Rs 110 is the highest possible for Meena."},{"kind":"numeric","prompt":"Aan and Bela each started with Rs 200. Aan spent Rs 65 more than Bela on paint. Bela needed at least a paintbrush, so she spent at least Rs 20. What is the LOWEST possible amount Bela could have spent?","answer":20,"explain":"The clue says Bela spent at least Rs 20, so the lowest possible amount she could have spent is exactly Rs 20."},{"kind":"mcq","prompt":"Sam and Priya each have Rs 100. Sam spent Rs 25 less than Priya on gloves. If Priya spent the most she possibly could (without going over Rs 100), how much did Sam spend?","options":["Rs 125","Rs 25","Rs 75","Rs 100"],"answer":2,"explain":"If Priya spent the maximum Rs 100, then Sam spent Rs 100 - 25 = Rs 75."},{"kind":"numeric","prompt":"Vik and Om each started with Rs 180. Vik spent Rs 50 more than Om on dustbins. What is the HIGHEST possible amount Om could have spent, without Vik spending more than Rs 180?","answer":130,"explain":"Vik = Om + 50 must be at most 180, so Om can spend at most Rs 130 (then Vik spends exactly Rs 180)."}]},{"id":"cv2","title":"Breaking the Budget","icon":"🧩","kind":"lesson","story":"The Clean Village Day committee has Rs 500 to spend on brooms, paint, and tree saplings. Help them break the big budget into smaller parts that add up correctly!","teach":[{"title":"What is decomposition?","body":"Decomposition means breaking one big total into smaller parts that are easier to handle. If you know the total and some of the parts, you can find the missing part by subtracting what you know from the total.","visual":"🧩"},{"title":"Checking your budget adds up","body":"After splitting money into parts, always add the parts back together — they must equal the original total. This is a great way to check your work in any budget puzzle.","visual":"✅"}],"questions":[{"kind":"numeric","prompt":"The committee has Rs 500 for Clean Village Day. They spend Rs 180 on brooms and Rs 150 on paint. How much money is left for tree saplings?","answer":170,"explain":"500 - 180 - 150 = 170, so Rs 170 is left for saplings."},{"kind":"numeric","prompt":"A budget of Rs 640 is split into 4 equal parts, one for each street to clean. How much money does each street get?","answer":160,"explain":"640 divided into 4 equal parts is 640 ÷ 4 = 160."},{"kind":"mcq","prompt":"The clean-up budget is Rs 900, split between Paint (Rs 320), Brooms (Rs 210), and Dustbins. How much was spent on dustbins?","options":["Rs 530","Rs 370","Rs 900","Rs 320"],"answer":1,"explain":"900 - 320 - 210 = 370, so Rs 370 was spent on dustbins."},{"kind":"numeric","prompt":"Rs 750 must be split between Team A and Team B so that Team A gets Rs 100 more than Team B, and together they use the whole Rs 750. How much does Team B get?","answer":325,"explain":"Two shares of Team B plus the extra Rs 100 make Rs 750, so Team B's share is (750 - 100) ÷ 2 = 325."}]},{"id":"cv3","title":"Who Spent What?","icon":"🗝️","kind":"lesson","story":"Four friends — Aisha, Bilal, Chetan, and Divya — went shopping for the village fair. Use the clues to figure out exactly how much each one spent!","teach":[{"title":"Using multiple clues together","body":"When there are several clues, use one clue to narrow things down, then check it against the OTHER clues too. The correct answer must satisfy every clue at the same time, not just one of them.","visual":"🗝️"},{"title":"Ordering people by amount","body":"Clues like 'more than' and 'less than' let you line people up from least to most, like beads on a string. Once you know the order, matching amounts to names gets much easier.","visual":"🔗"}],"questions":[{"kind":"mcq","prompt":"Aisha spent more than Bilal. Bilal spent more than Chetan. Chetan spent Rs 40. Aisha spent Rs 90. Which of these could be Bilal's amount?","options":["Rs 95","Rs 30","Rs 40","Rs 65"],"answer":3,"explain":"Bilal must have spent more than Rs 40 (Chetan) and less than Rs 90 (Aisha). Rs 65 fits; the other options don't."},{"kind":"mcq","prompt":"Three friends spent Rs 20, Rs 35, and Rs 50 in some order. Clue 1: Divya spent the most. Clue 2: Bilal spent less than Divya but more than Chetan. Who spent Rs 20?","options":["Cannot be determined","Bilal","Divya","Chetan"],"answer":3,"explain":"Divya spent the most (Rs 50) and Bilal is in the middle (Rs 35), so Chetan spent the least, Rs 20."},{"kind":"numeric","prompt":"Four friends spent a total of Rs 260 together. Aisha spent Rs 90, Bilal spent Rs 65, and Chetan spent Rs 40. How much did Divya spend?","answer":65,"explain":"260 - 90 - 65 - 40 = 65, so Divya spent Rs 65."},{"kind":"mcq","prompt":"In a group of 3 volunteers, Priya spent Rs 15 more than Om, and Om spent Rs 15 more than Sam. If Sam spent Rs 20, how much did Priya spend?","options":["Rs 20","Rs 65","Rs 35","Rs 50"],"answer":3,"explain":"Om spent 20 + 15 = 35, and Priya spent 35 + 15 = 50."}]},{"id":"cv4","title":"Highest and Lowest Possible","icon":"⚖️","kind":"lesson","story":"The Clean Village Day prize goes to whoever can crack the trickiest budget puzzle! Sharpen your skills at finding the biggest and smallest amounts that still fit the clues.","teach":[{"title":"Testing the extreme values","body":"To find the highest possible value, push every clue to its limit in the direction that makes your target as big as possible. To find the lowest, push the other way. Always re-check your final answer against all the clues.","visual":"⚖️"},{"title":"Watch for hidden limits","body":"A total budget, a 'not more than' clue, or 'cannot be negative' are all hidden limits. Miss one of these and your 'highest' or 'lowest' answer will be wrong, even if the arithmetic is correct.","visual":"🚧"}],"questions":[{"kind":"mcq","prompt":"A stall has Rs 300 to spend on flags and balloons combined. Flags must cost at least Rs 50. What is the HIGHEST possible amount that can be spent on balloons?","options":["Rs 250","Rs 200","Rs 50","Rs 300"],"answer":0,"explain":"Since flags cost at least Rs 50, balloons can get at most 300 - 50 = Rs 250."},{"kind":"numeric","prompt":"A budget of Rs 400 is shared between Team X and Team Y. Team X must get at least Rs 120, and Team Y must get at least Rs 80. What is the LOWEST possible amount Team Y could get?","answer":80,"explain":"Team Y needs at least Rs 80. Even if Team X takes the rest (Rs 320), Team Y still gets its minimum, Rs 80."},{"kind":"numeric","prompt":"A charity box collected Rs 150 from three donors. No single donor could give more than Rs 60. If the top donor gave the maximum allowed amount, how much did the other two donors give together?","answer":90,"explain":"150 - 60 = 90, so together the other two donors gave Rs 90."},{"kind":"mcq","prompt":"Rahim has Rs 500 for the fair. He must spend at least Rs 100 on food and at least Rs 150 on rides. What is the highest amount he could spend on games, using his full Rs 500 budget?","options":["Rs 350","Rs 500","Rs 250","Rs 150"],"answer":2,"explain":"500 - 100 - 150 = 250 is the most left over for games after the minimum spends on food and rides."}]},{"id":"cv5","title":"Sharing and Splitting","icon":"➗","kind":"lesson","story":"Clean Village Day needs volunteer teams! Money for T-shirts, snacks, and tools must be split fairly among the teams — but sometimes there's a little left over.","teach":[{"title":"Equal sharing","body":"To split money equally among a number of people, divide the total by the number of people. If it doesn't divide evenly, there will be a remainder left over.","visual":"➗"},{"title":"Working with remainders","body":"When money can't be split perfectly evenly, first give everyone the same whole-rupee share, then figure out what's left over. That leftover amount needs a special plan, like being saved for later.","visual":"🪙"}],"questions":[{"kind":"numeric","prompt":"Rs 360 is shared equally among 6 volunteers. How much does each volunteer get?","answer":60,"explain":"360 ÷ 6 = 60, so each volunteer gets Rs 60."},{"kind":"numeric","prompt":"Rs 250 is shared equally among 4 volunteers, giving each the same whole-rupee amount. How much money is LEFT OVER after sharing?","answer":2,"explain":"Each volunteer gets Rs 62 (4 x 62 = 248), leaving Rs 2 left over from Rs 250."},{"kind":"mcq","prompt":"A team of 5 volunteers must share Rs 175 equally. How much does each person get?","options":["Rs 25","Rs 40","Rs 35","Rs 30"],"answer":2,"explain":"175 ÷ 5 = 35, so each person gets Rs 35."},{"kind":"numeric","prompt":"Rs 90 in snack money is split between 3 teams so that each team after the first gets Rs 10 more than the one before it. How much does the first team get?","answer":20,"explain":"Three times the first team's share, plus the extra 10 + 20, makes 90. So the first team's share is (90 - 30) ÷ 3 = 20."}]},{"id":"cv6","title":"The Village Ledger","icon":"📒","kind":"lesson","story":"The clean-up ledger has smudged ink! Only careful, step-by-step deduction can reveal exactly who bought what — and for how much.","teach":[{"title":"Process of elimination","body":"When you don't know an exact answer yet, cross out any option that breaks a clue. Keep checking the clues against what's left until only one possibility remains — that's your answer!","visual":"✏️"},{"title":"Combining clues step by step","body":"Big ledger puzzles feel easier if you solve them one clue at a time, writing down what you've figured out so far before moving to the next clue. Don't try to do it all in your head at once!","visual":"📒"}],"questions":[{"kind":"mcq","prompt":"Four items were bought for Rs 20, Rs 35, Rs 45, and Rs 60 — one each by Anu, Ben, Cara, and Dev. Clue 1: Cara paid the most. Clue 2: Ben paid the least. Clue 3: Anu paid more than Dev. Who paid Rs 45?","options":["Anu","Cara","Dev","Ben"],"answer":0,"explain":"Cara paid the most (Rs 60) and Ben the least (Rs 20). Since Anu paid more than Dev, Anu gets Rs 45 and Dev gets Rs 35."},{"kind":"numeric","prompt":"Using the same four friends and amounts (Rs 20, Rs 35, Rs 45, Rs 60) from the last clue, how much more did Cara pay than Ben?","answer":40,"explain":"Cara paid Rs 60 and Ben paid Rs 20, so the difference is 60 - 20 = 40."},{"kind":"mcq","prompt":"Three shops sell brooms for Rs 30, Rs 45, and Rs 55, one price each. Clue 1: Shop P's broom costs more than Shop Q's. Clue 2: Shop R's broom is the cheapest. What is Shop Q's price?","options":["Rs 45","Rs 55","Rs 30","Cannot be determined"],"answer":0,"explain":"Shop R is the cheapest at Rs 30. Since Shop P costs more than Shop Q, P must be Rs 55 and Q must be Rs 45."},{"kind":"numeric","prompt":"The whole village ledger shows Rs 500 was collected. Rs 220 came from donations, and the rest came equally from 4 stalls. How much did each stall contribute?","answer":70,"explain":"500 - 220 = 280 came from the stalls, and 280 ÷ 4 = 70 from each stall."}]},{"id":"cv-boss","title":"The Great Clean-Up Challenge","icon":"🏆","kind":"boss","story":"Grubby Gustav, the Litter Lord, has scattered rubbish and mixed-up money clues all over the village square. Solve every puzzle to sweep him out for good and win the Cleanest Village trophy!","boss":{"name":"Grubby Gustav, the Litter Lord","taunt":"Ha! Your brooms are no match for my mountain of muddled money puzzles!"},"teach":[{"title":"Bring it all together","body":"This final challenge mixes spending clues, budget decomposition, and highest/lowest reasoning. Take each question one step at a time, just like you practiced in every village lesson.","visual":"🏆"}],"questions":[{"kind":"mcq","prompt":"Nita and Omar each started with Rs 250. Nita spent Rs 70 more than Omar. What is the HIGHEST possible amount Omar could have spent, if Nita cannot spend more than Rs 250?","options":["Rs 110","Rs 250","Rs 70","Rs 180"],"answer":3,"explain":"Nita = Omar + 70 must be at most 250, so Omar's highest possible spend is Rs 180 (then Nita spends exactly Rs 250)."},{"kind":"numeric","prompt":"The clean-up committee has Rs 720 to split equally across 3 zones. How much money does each zone get?","answer":240,"explain":"720 ÷ 3 = 240, so each zone gets Rs 240."},{"kind":"mcq","prompt":"Three friends spent Rs 25, Rs 40, and Rs 55 in some order. Clue 1: Zara spent the most. Clue 2: Yash spent less than Zara but more than Farah. Who spent Rs 40?","options":["Zara","Yash","Farah","Cannot be determined"],"answer":1,"explain":"Zara spent the most (Rs 55) and Farah spent the least (Rs 25), so Yash, in the middle, spent Rs 40."},{"kind":"numeric","prompt":"A budget of Rs 640 is split between Team Clean and Team Green so that Team Clean gets Rs 80 more than Team Green, and together they use the whole budget. How much does Team Green get?","answer":280,"explain":"Two shares of Team Green plus the extra Rs 80 make Rs 640, so Team Green's share is (640 - 80) ÷ 2 = 280."},{"kind":"numeric","prompt":"Rs 313 is shared equally among 5 volunteers, giving each the same whole-rupee amount. How much money is LEFT OVER?","answer":3,"explain":"Each volunteer gets Rs 62 (5 x 62 = 310), leaving Rs 3 left over from Rs 313."},{"kind":"mcq","prompt":"A stall has Rs 400 for snacks and drinks combined. Snacks must cost at least Rs 90. What is the HIGHEST possible amount that can be spent on drinks?","options":["Rs 290","Rs 400","Rs 90","Rs 310"],"answer":3,"explain":"Since snacks cost at least Rs 90, drinks can get at most 400 - 90 = Rs 310."},{"kind":"mcq","prompt":"Four items cost Rs 15, Rs 30, Rs 50, and Rs 65 — bought one each by Kiran, Leo, Maya, and Nash. Clue 1: Maya paid the most. Clue 2: Kiran paid the least. Clue 3: Leo paid more than Nash. Who paid Rs 50?","options":["Kiran","Nash","Leo","Maya"],"answer":2,"explain":"Maya paid the most (Rs 65) and Kiran paid the least (Rs 15). Since Leo paid more than Nash, Leo gets Rs 50 and Nash gets Rs 30."}]}]},{"id":"weighitpourit4","index":7,"name":"Weigh It, Pour It","subtitle":"Computational Thinking — Chapter 8","emoji":"⚖️","palette":{"from":"#a78bfa","to":"#4c1d95"},"lessons":[{"id":"wp1","title":"Balance Scale Basics","icon":"⚖️","kind":"lesson","story":"Welcome to the Puzzle Bazaar! The old shopkeeper trusts only her two-pan balance scale to settle any argument. Help her read the scale so every trade is fair.","teach":[{"title":"How a balance works","body":"A balance scale has two pans hanging from a middle point. If both sides weigh exactly the same, the scale stays level — we call this 'balanced'. Whichever side is heavier always dips down, and the lighter side rises up.","visual":"⚖️"}],"questions":[{"kind":"mcq","prompt":"A balance scale has an apple on the left pan and a mango on the right pan. The scale is perfectly level. What does this tell us?","options":["The apple is heavier","The apple and mango weigh the same","The mango is heavier","We cannot compare them"],"answer":1,"explain":"A level scale means both pans hold equal weight, so the apple and mango weigh the same."},{"kind":"mcq","prompt":"On a balance scale, the left pan (with a toy car) dips down, and the right pan (with a ball) rises up. Which is heavier?","options":["The toy car","The ball","Both are equal","Cannot tell"],"answer":0,"explain":"The pan that dips down always holds the heavier object, so the toy car is heavier."},{"kind":"numeric","prompt":"A ball weighs 4 kg and a book weighs 7 kg. You put both on the left pan, and a single box weighing 11 kg on the right pan. What is the difference in weight between the two sides, in kg?","answer":0,"explain":"Ball + book = 4 + 7 = 11 kg, which is exactly equal to the box, so the difference is 0 kg — the scale balances."},{"kind":"mcq","prompt":"Which pan will go DOWN if the left pan holds a 6 kg sack and the right pan holds a 9 kg sack?","options":["The right pan","The left pan","Neither, they balance","Both go down"],"answer":0,"explain":"9 kg is heavier than 6 kg, so the right pan (with the 9 kg sack) goes down."}]},{"id":"wp2","title":"Weight-Swapping Riddles","icon":"🔺","kind":"lesson","story":"The Bazaar's riddle-loving parrot squawks puzzles about shapes on scales all day long. Crack her weight-swapping riddles to earn the next clue on your quest!","teach":[{"title":"Swapping equal weights","body":"If two things together balance a third thing, you can always swap them for it — their total weight is exactly the same. This trick lets you figure out the weight of something you've never even put on a scale!","visual":"🔄"},{"title":"Building new balances","body":"Once you know one balance is true, you can use it inside another puzzle. Replace a shape with its known weight, then simply add the numbers up.","visual":"➕"}],"questions":[{"kind":"numeric","prompt":"On a balance scale, 1 circle + 1 square balance 1 triangle. The circle weighs 3 kg and the square weighs 5 kg. How many kg does the triangle weigh?","answer":8,"explain":"3 kg + 5 kg = 8 kg, so the triangle must weigh 8 kg to balance them."},{"kind":"numeric","prompt":"2 triangles balance 1 star. Each triangle weighs 8 kg. How many kg does the star weigh?","answer":16,"explain":"2 triangles = 8 + 8 = 16 kg, so the star weighs 16 kg."},{"kind":"mcq","prompt":"1 star balances 2 triangles, and 1 triangle balances 1 circle + 1 square. The circle weighs 3 kg and the square weighs 5 kg. What is the weight of the star?","options":["11 kg","24 kg","8 kg","16 kg"],"answer":3,"explain":"Each triangle weighs 3 + 5 = 8 kg, and the star equals 2 triangles, so 8 + 8 = 16 kg."},{"kind":"mcq","prompt":"On a scale, 3 identical marbles balance 1 toy duck. The toy duck weighs 12 kg. How much does ONE marble weigh?","options":["3 kg","12 kg","4 kg","36 kg"],"answer":2,"explain":"12 kg shared equally among 3 marbles is 12 ÷ 3 = 4 kg each."},{"kind":"numeric","prompt":"2 pencils balance 1 eraser, and the eraser weighs 6 kg. How much would 5 pencils weigh in total? (Hint: find the weight of 1 pencil first.)","answer":15,"explain":"2 pencils = 6 kg, so 1 pencil = 3 kg. Then 5 pencils = 5 × 3 = 15 kg."}]},{"id":"wp3","title":"Heavier or Lighter Chains","icon":"🧩","kind":"lesson","story":"Three animal friends at the bazaar are arguing about who is heaviest, and nobody has a scale big enough! Use their clues to settle the argument with pure logic.","teach":[{"title":"Chains of comparison","body":"If A is heavier than B, and B is heavier than C, then A must be heavier than C too — even without ever weighing A and C together! This is called chaining clues.","visual":"🔗"},{"title":"Working step by step","body":"When a puzzle gives many clues, write down what you know first. Then use one clue at a time to find the next fact, just like climbing down a staircase.","visual":"🪜"}],"questions":[{"kind":"numeric","prompt":"Riya weighs 5 kg less than her brother Sam. Sam weighs 8 kg more than their mother. Their mother weighs 60 kg. How much does Riya weigh, in kg?","answer":63,"explain":"Sam = 60 + 8 = 68 kg. Riya = 68 − 5 = 63 kg."},{"kind":"mcq","prompt":"A monkey is heavier than a rabbit. A rabbit is heavier than a mouse. Which statement is DEFINITELY true?","options":["Nothing can be said for sure","The monkey is heavier than the mouse","The mouse is heavier than the monkey","The rabbit is the heaviest of the three"],"answer":1,"explain":"Monkey > rabbit and rabbit > mouse, so chaining the clues gives monkey > mouse."},{"kind":"mcq","prompt":"Neha is heavier than Priya. Priya is heavier than Tara. Tara is heavier than Zoya. Who is the LIGHTEST?","options":["Neha","Zoya","Tara","Priya"],"answer":1,"explain":"The chain is Neha > Priya > Tara > Zoya, so Zoya is at the bottom — the lightest."},{"kind":"numeric","prompt":"A kitten weighs 2 kg less than a puppy. The puppy weighs 3 kg less than a baby goat. The baby goat weighs 15 kg. How much does the kitten weigh, in kg?","answer":10,"explain":"Puppy = 15 − 3 = 12 kg. Kitten = 12 − 2 = 10 kg."},{"kind":"mcq","prompt":"Four friends compare bags: Bag A is heavier than Bag B. Bag C is heavier than Bag A. Bag B is heavier than Bag D. Which bag is the heaviest?","options":["Bag D","Bag C","Bag B","Bag A"],"answer":1,"explain":"Chaining the clues gives C > A > B > D, so Bag C is the heaviest."}]},{"id":"wp4","title":"Pouring Between Jugs","icon":"🫙","kind":"lesson","story":"The bazaar's water seller has only two odd-sized jugs and thirsty customers who need EXACT amounts. Help her measure water perfectly using only pouring, filling, and emptying!","teach":[{"title":"Three pouring moves","body":"With any jugs, you can only do three things: FILL a jug completely from a tap, EMPTY a jug completely, or POUR from one jug into another until the first jug is empty or the second jug is full. No guessing halfway amounts allowed!","visual":"💧"}],"questions":[{"kind":"mcq","prompt":"You have a 5-litre jug and a 3-litre jug, both empty. Which of these is a LEGAL pouring move?","options":["Weigh the jug instead of pouring","Pour exactly 2 litres into it by guessing","Fill the 5-litre jug completely from a tap","Mark 1 litre on the side using a ruler"],"answer":2,"explain":"The only allowed moves are filling a jug completely, emptying it completely, or pouring between jugs."},{"kind":"numeric","prompt":"You have a full 5-litre jug and an empty 3-litre jug. You pour from the 5-litre jug into the 3-litre jug until the 3-litre jug is full. How many litres are left in the 5-litre jug?","answer":2,"explain":"5 litres poured until 3 litres go into the small jug leaves 5 − 3 = 2 litres behind."},{"kind":"numeric","prompt":"You have an empty 8-litre jug and an empty 3-litre jug. You fill the 3-litre jug and pour it into the 8-litre jug. You do this a second time (fill the 3-litre jug again, pour it in again). How many litres are now in the 8-litre jug?","answer":6,"explain":"Two pours of 3 litres each add up to 3 + 3 = 6 litres in the 8-litre jug."},{"kind":"numeric","prompt":"A 10-litre jug is full. You pour it into empty 4-litre jugs, filling each one completely before starting the next. How many litres of water are left over once you can no longer fill a full 4-litre jug?","answer":2,"explain":"10 litres makes two full 4-litre jugs (8 litres used), leaving 10 − 8 = 2 litres over."},{"kind":"mcq","prompt":"You want EXACTLY 4 litres using only a 5-litre jug and a 3-litre jug (neither has markings). What is a sensible FIRST step?","options":["Guess and pour a little water at a time","Fill the 5-litre jug completely","Fill the 3-litre jug only halfway","Weigh the water instead of measuring it"],"answer":1,"explain":"Jug puzzles always start by filling one jug completely — that's the only legal first move."}]},{"id":"wp5","title":"The Exact-Litre Challenge","icon":"🧮","kind":"lesson","story":"The water seller's trickiest customer wants EXACTLY 4 litres — and there's only a 3-litre jug and a 5-litre jug to work with! Walk through the pours with her, one careful step at a time.","teach":[{"title":"Planning your pours","body":"Tricky jug puzzles are solved one careful move at a time. Keep track of exactly how much water is in each jug after every single pour, just like following a recipe step by step.","visual":"📝"}],"questions":[{"kind":"numeric","prompt":"Start: both the 3-litre jug and the 5-litre jug are empty. Step 1 — fill the 5-litre jug completely. How many litres are in the 5-litre jug now?","answer":5,"explain":"Filling a jug completely means it now holds its full capacity: 5 litres."},{"kind":"numeric","prompt":"Step 2 — pour from the full 5-litre jug into the empty 3-litre jug until the 3-litre jug is full. How many litres are LEFT in the 5-litre jug?","answer":2,"explain":"5 litres minus the 3 litres that moved into the small jug leaves 5 − 3 = 2 litres."},{"kind":"numeric","prompt":"Step 3 — empty the 3-litre jug completely, then pour the 2 litres remaining in the 5-litre jug into the empty 3-litre jug. How many litres are now in the 3-litre jug?","answer":2,"explain":"All 2 litres from the 5-litre jug move into the empty 3-litre jug, so it now holds 2 litres."},{"kind":"numeric","prompt":"Step 4 — fill the 5-litre jug completely again. The 3-litre jug already has 2 litres in it. How many MORE litres are needed to fill the 3-litre jug to the top?","answer":1,"explain":"The 3-litre jug can hold 3 litres total, and it already has 2, so it needs only 1 more litre."},{"kind":"numeric","prompt":"Step 5 — pour from the full 5-litre jug into the 3-litre jug until the 3-litre jug is full (this adds 1 litre). How many litres are LEFT in the 5-litre jug now?","answer":4,"explain":"5 litres minus the 1 litre poured out leaves 5 − 1 = 4 litres — exactly the amount the customer wanted!"}]},{"id":"wp6","title":"Weight & Money at the Market","icon":"🛍️","kind":"lesson","story":"It's market day! Help the bazaar's shoppers figure out exact weights and costs before their baskets get too heavy or their coins run out.","teach":[{"title":"Reading word problems carefully","body":"Word problems hide numbers inside sentences. First decide whether you need to add, subtract, multiply, or compare — then work through the numbers one step at a time.","visual":"🛒"}],"questions":[{"kind":"numeric","prompt":"A delivery van can carry a maximum of 50 kg. It already has a box weighing 32 kg inside. How many MORE kilograms can be added without going over the limit?","answer":18,"explain":"50 − 32 = 18 kg of space is left in the van."},{"kind":"numeric","prompt":"Apples cost Rs 20 per kg and oranges cost Rs 15 per kg. Mother's list needs 2 kg apples and 3 kg oranges. Aarav bought 3 kg apples and 2 kg oranges instead. How many EXTRA rupees did he spend compared to the list?","answer":5,"explain":"List cost = 2×20 + 3×15 = 40 + 45 = 85. Aarav's cost = 3×20 + 2×15 = 60 + 30 = 90. Extra spent = 90 − 85 = 5 rupees."},{"kind":"mcq","prompt":"A gift box can hold up to 25 kg. It already contains a toy weighing 9 kg and a book weighing 4 kg. What is the MAXIMUM additional weight that can still be added?","options":["12 kg","13 kg","9 kg","14 kg"],"answer":0,"explain":"25 − 9 − 4 = 12 kg of space remains in the box."},{"kind":"numeric","prompt":"Sugar costs Rs 40 per kg and rice costs Rs 30 per kg. A shopper buys 2 kg sugar and 3 kg rice. How much does she spend in total, in rupees?","answer":170,"explain":"2×40 = 80 for sugar, 3×30 = 90 for rice, and 80 + 90 = 170 rupees total."},{"kind":"mcq","prompt":"A shopkeeper has a 20 kg sack of flour. She sells 7 kg to one customer and 6 kg to another. How many kilograms of flour are left in the sack?","options":["6 kg","8 kg","13 kg","7 kg"],"answer":3,"explain":"20 − 7 − 6 = 7 kg of flour remains."}]},{"id":"wp-boss","title":"Ozul the Overweight Ogre","icon":"🏆","kind":"boss","boss":{"name":"Ozul the Overweight Ogre","taunt":"You think you can out-weigh me? Prove it with your numbers, tiny trader!"},"story":"Ozul guards the bazaar's treasure vault with a giant balance scale in one hand and two enormous jugs in the other. Solve every kind of puzzle from this world to prove you deserve to pass!","teach":[],"questions":[{"kind":"mcq","prompt":"A balance scale is perfectly level with a kite on the left pan and a drum on the right pan. What does this tell us?","options":["The kite and drum weigh the same","Nothing at all","The drum is heavier","The kite is heavier"],"answer":0,"explain":"A level scale always means both pans hold equal weight."},{"kind":"numeric","prompt":"1 cup + 1 spoon balance 1 plate. The cup weighs 4 kg and the spoon weighs 2 kg. How many kg does the plate weigh?","answer":6,"explain":"4 kg + 2 kg = 6 kg, so the plate must weigh 6 kg to balance them."},{"kind":"mcq","prompt":"Ladoo is heavier than Jalebi. Jalebi is heavier than Barfi. Which statement is DEFINITELY true?","options":["Ladoo is heavier than Barfi","Jalebi is the heaviest of the three","Nothing can be said for sure","Barfi is heavier than Ladoo"],"answer":0,"explain":"Chaining the clues: Ladoo > Jalebi and Jalebi > Barfi, so Ladoo > Barfi."},{"kind":"numeric","prompt":"A basket can carry a maximum of 15 kg. It already has 9 kg of vegetables inside. How many more kilograms can be added?","answer":6,"explain":"15 − 9 = 6 kg of space is left in the basket."},{"kind":"numeric","prompt":"You have a full 7-litre jug and an empty 4-litre jug. You pour from the 7-litre jug into the 4-litre jug until the 4-litre jug is full. How many litres are left in the 7-litre jug?","answer":3,"explain":"7 − 4 = 3 litres remain in the larger jug."},{"kind":"numeric","prompt":"You have an empty 6-litre jug and an empty 4-litre jug. You fill the 4-litre jug and pour all of it into the 6-litre jug. Then you fill the 4-litre jug again. How many more litres are needed to completely fill the 6-litre jug (which already has 4 litres in it)?","answer":2,"explain":"The 6-litre jug already holds 4 litres, so it needs 6 − 4 = 2 more litres to be completely full."},{"kind":"mcq","prompt":"Notebooks cost Rs 25 each and pencils cost Rs 5 each. Meera buys 2 notebooks and 4 pencils. How much does she spend in total?","options":["Rs 70","Rs 60","Rs 75","Rs 65"],"answer":0,"explain":"2×25 = 50 for notebooks, 4×5 = 20 for pencils, and 50 + 20 = 70 rupees total."}]}]},{"id":"equalgroups4","index":8,"name":"Equal Groups","subtitle":"Computational Thinking — Chapter 9","emoji":"🟰","palette":{"from":"#38bdf8","to":"#0c4a6e"},"lessons":[{"id":"eg1","title":"The Backward Number Trick","icon":"🔑","kind":"lesson","story":"A carved chest blocks the path out of the puzzle garden. Its riddle gives you a clue about a hidden number — you must think backward from the answer to find it.","teach":[{"title":"Think in equal groups","body":"If a number is tripled, that's 3 equal groups of it. Adding the number once more to get triple means you're really just adding 2 extra equal groups.","visual":"🧩"},{"title":"Undo the adding","body":"So if adding 22 to a number gives 3 times the number, then 22 must be exactly 2 equal groups of that number. Divide 22 by 2 to find one group: 11.","visual":"➗"}],"questions":[{"kind":"numeric","prompt":"When 10 is added to a number, the result is three times the number. What is the number?","answer":5,"explain":"3 times the number minus the number itself leaves 2 equal groups equal to 10, so one group is 5."},{"kind":"mcq","prompt":"When 8 is added to a number, the result is three times the number. What was the number?","options":["6","2","4","8"],"answer":2,"explain":"The extra 2 equal groups equal 8, so one group is 8 ÷ 2 = 4."},{"kind":"numeric","prompt":"When 30 is added to a number, the result is four times the number. What is the number?","answer":10,"explain":"4 times the number minus the number leaves 3 equal groups equal to 30, so one group is 10."},{"kind":"numeric","prompt":"When 24 is added to a number, the result is four times the number. What was the number?","answer":8,"explain":"3 equal groups equal 24 (since 4 times minus 1 time = 3 times), so one group is 8."}]},{"id":"eg2","title":"Sharing Into Equal Groups","icon":"🧺","kind":"lesson","story":"A friendly basket-dragon will only let you pass if you can split its fruit hoard into perfectly equal groups — and tell it exactly what's left over.","teach":[{"title":"Equal groups and remainder","body":"When you share a collection equally, sometimes everything fits into groups exactly, and sometimes a few items are left over. That leftover amount is called the remainder.","visual":"🍎"},{"title":"Finding group size","body":"If you know the total and how many groups you want, divide the total by the number of groups to find how many go in each group.","visual":"🔢"}],"questions":[{"kind":"numeric","prompt":"36 mangoes are shared equally among 6 baskets. How many mangoes go in each basket?","answer":6,"explain":"36 ÷ 6 = 6 mangoes in each basket."},{"kind":"numeric","prompt":"45 sweets are shared as equally as possible among 7 friends. How many sweets are left over?","answer":3,"explain":"45 ÷ 7 = 6 sweets each, using 42 sweets, with 3 left over."},{"kind":"mcq","prompt":"A gardener has 50 saplings and plants them in rows of 8. How many full rows can she make?","options":["8","6","2","7"],"answer":1,"explain":"50 ÷ 8 = 6 full rows, with 2 saplings left over."},{"kind":"numeric","prompt":"63 pencils are packed into boxes of 9 pencils each. How many boxes are needed?","answer":7,"explain":"63 ÷ 9 = 7 boxes exactly."}]},{"id":"eg3","title":"Doubling and Halving Patterns","icon":"🌿","kind":"lesson","story":"A magic vine in the jungle doubles in length every single night. To predict its past and future size, you must think in doubles and halves.","teach":[{"title":"Doubling patterns","body":"In a doubling pattern, each new value is twice the one before it: 3, 6, 12, 24 — every step, multiply by 2.","visual":"🐛"},{"title":"Halving backward","body":"To find the value one step BEFORE a doubling step, do the opposite of doubling — divide by 2 instead of multiplying.","visual":"↩️"}],"questions":[{"kind":"numeric","prompt":"A patch of moss doubles in size every day. If it covers the whole pond on day 15, on which day did it cover exactly half the pond?","answer":14,"explain":"Since it doubles each day, the day before full is always half — day 14."},{"kind":"mcq","prompt":"A number pattern is 3, 6, 12, 24, 48. What is the rule?","options":["Each term is 3 more than the previous term","Each term is double the previous term","Each term is triple the previous term","Each term is half the previous term"],"answer":1,"explain":"6 is double 3, 12 is double 6, and so on — the rule is doubling."},{"kind":"numeric","prompt":"A bacteria colony doubles every hour. It has 5 bacteria now. How many will it have after 3 hours?","answer":40,"explain":"5 → 10 → 20 → 40, doubling three times."},{"kind":"numeric","prompt":"A lantern's glow doubles every night. After 10 nights it fully lights the whole cave. On which night was it covering exactly one-quarter of the cave?","answer":8,"explain":"Half the cave was covered on night 9, so a quarter was covered on night 8 (two nights before full)."}]},{"id":"eg4","title":"Multiples and Positions","icon":"🧙","kind":"lesson","story":"In the Enchanted Line-Up Hall, wizards only stand at positions that are multiples of a chosen number. Work out exactly where each one stands.","teach":[{"title":"Multiples","body":"A multiple of a number is what you get by multiplying it by 1, 2, 3, and so on. Multiples of 10 are 10, 20, 30, 40 …","visual":"✨"},{"title":"Position from the other end","body":"In a row of N people, someone standing at position p from the left is at position (N minus p, plus 1) from the right end.","visual":"↔️"}],"questions":[{"kind":"numeric","prompt":"In a row of 40 children, Aarav and Vihaan both stand at positions that are multiples of 10, counted from the left end. Vihaan's position is twice Aarav's position, and Aarav is NOT standing at the 10th position. What is Vihaan's position from the left end?","answer":40,"explain":"The only multiples of 10 up to 40 are 10, 20, 30, 40. Since Aarav isn't at 10 and Vihaan = 2 × Aarav must also be a multiple of 10 within 40, Aarav must be at 20, making Vihaan at 40."},{"kind":"numeric","prompt":"Using the same row of 40 children, what is Vihaan's position counted from the right end?","answer":1,"explain":"Vihaan stands at position 40 from the left, which is the very last spot — position 1 from the right."},{"kind":"mcq","prompt":"In that same row, what is Aarav's position from the left end?","options":["10","40","30","20"],"answer":3,"explain":"Aarav stands at position 20 from the left, so Vihaan (twice that) stands at 40."},{"kind":"numeric","prompt":"In a row of 50 students, a teacher stands at a position that is a multiple of 5. Her position from the right end is 46. What is her position from the left end?","answer":5,"explain":"Position from left = 50 − 46 + 1 = 5, and 5 is indeed a multiple of 5."}]},{"id":"eg5","title":"Rate and Groups","icon":"🐫","kind":"lesson","story":"A desert caravan needs equal-sized carts and coin-pouches to cross the sands. Figure out how much fits in each equal group.","teach":[{"title":"Same amount every group","body":"If every coin in a pile has the same value, multiply the number of coins by that value to find the total amount — that's counting in equal groups.","visual":"🪙"},{"title":"Finding a hidden capacity","body":"If you know how many vehicles are needed to carry different group sizes, you can figure out how many each vehicle carries by testing whole numbers that fit both clues.","visual":"🚐"}],"questions":[{"kind":"numeric","prompt":"I am a van. To carry a group of 75 hikers, 9 vans like me are needed. To carry a group of 70 hikers, 8 vans like me are needed. How many hikers can I carry at most?","answer":9,"explain":"With capacity 9: 8 vans hold at most 72 (not enough for 75, so 9 vans are needed), and 7 vans hold at most 63 (not enough for 70, so 8 vans are needed). Capacity 9 fits both clues."},{"kind":"mcq","prompt":"Meera has some 10-rupee coins. To find out how much money she has in total, what should she do?","options":["Divide the number of coins by 10","Add 10 to the number of coins","Multiply the number of coins by 5","Multiply the number of coins by 10"],"answer":3,"explain":"Each coin is worth 10 rupees, so the total is the number of coins multiplied by 10."},{"kind":"numeric","prompt":"Kabir has 14 five-rupee coins. How much money does he have in total?","answer":70,"explain":"14 × 5 = 70 rupees."},{"kind":"numeric","prompt":"A shopkeeper packs marbles into bags of 12 each. He has 9 full bags and 5 loose marbles left over. How many marbles does he have in total?","answer":113,"explain":"9 × 12 = 108, plus 5 loose marbles = 113."}]},{"id":"eg6","title":"Number Chains and Substitution","icon":"🌳","kind":"lesson","story":"A puzzle tree grows number-leaves — each leaf's value depends on another leaf. Follow the chain of clues to work out every hidden value.","teach":[{"title":"Chains of relationships","body":"Sometimes one value is described using another, like 'B is double A'. Work out the chain one step at a time, starting from the value you already know.","visual":"🔗"},{"title":"Comparing values","body":"Once you know each letter's value, you can work out expressions like 'sum' or 'difference' just like ordinary sums — one careful step at a time.","visual":"⚖️"}],"questions":[{"kind":"numeric","prompt":"If P = 4, Q is double P, and R is double Q, what is R?","answer":16,"explain":"Q = 2 × 4 = 8, then R = 2 × 8 = 16."},{"kind":"numeric","prompt":"A sequence follows the rule 'multiply by 3 each time': 2, 6, 18, 54, ... What is the next number?","answer":162,"explain":"54 × 3 = 162."},{"kind":"mcq","prompt":"A sequence is 5, 10, 20, 40, 80. What is the rule governing it?","options":["Each term is double the previous term","Each term is triple the previous term","Each term is 5 more than the previous term","Each term is half the previous term"],"answer":0,"explain":"10 is double 5, 20 is double 10, and so on."},{"kind":"numeric","prompt":"If X = 3, Y is double X, and Z is double Y, what is Y + Z?","answer":18,"explain":"Y = 2 × 3 = 6, Z = 2 × 6 = 12, so Y + Z = 6 + 12 = 18."}]},{"id":"eg-boss","title":"The Equal Groups Guardian","icon":"🤖","kind":"boss","boss":{"name":"Equal Groups Guardian","taunt":"My gears only turn for those who can reason their way to the hidden number!"},"story":"At the heart of the puzzle garden stands the Equal Groups Guardian, its lock built from six spinning gears. Solve each gear's riddle to shut it down for good.","teach":[],"questions":[{"kind":"numeric","prompt":"When 18 is added to a number, the result is four times the number. What is the number?","answer":6,"explain":"3 equal groups of the number equal 18 (since 4 times minus 1 time = 3 times), so one group is 6."},{"kind":"numeric","prompt":"58 oranges are shared as equally as possible into 8 crates. How many oranges are left over?","answer":2,"explain":"58 ÷ 8 = 7 in each crate, using 56 oranges, with 2 left over."},{"kind":"mcq","prompt":"A puddle's ice doubles in area every day and covers the whole puddle on day 12. On which day did it cover exactly half the puddle?","options":["Day 11","Day 24","Day 6","Day 10"],"answer":0,"explain":"Since it doubles each day, the day right before full covering is always the half-covered day — day 11."},{"kind":"numeric","prompt":"In a row of 30 dancers, Priya and Rohan stand at positions that are multiples of 5, counted from the left end. Rohan's position is three times Priya's position, and Priya is NOT at the 5th position. What is Rohan's position from the left end?","answer":30,"explain":"Priya must be at position 10 (the only multiple of 5, other than 5 itself, whose triple is also a multiple of 5 within 30), so Rohan stands at 3 × 10 = 30."},{"kind":"numeric","prompt":"Kiran has 16 two-rupee coins. How much money does she have in total?","answer":32,"explain":"16 × 2 = 32 rupees."},{"kind":"numeric","prompt":"If M = 5, N is double M, and P is double N, what is the value of N + P?","answer":30,"explain":"N = 2 × 5 = 10, P = 2 × 10 = 20, so N + P = 10 + 20 = 30."}]}]},{"id":"elephantstigersleopards4","index":9,"name":"Elephants, Tigers, and Leopards","subtitle":"Computational Thinking — Chapter 10","emoji":"🐘","palette":{"from":"#f59e0b","to":"#78350f"},"lessons":[{"id":"et1","title":"The Jungle Digit Code","icon":"🔢","kind":"lesson","story":"The Forest Ranger's logbook locks its gate with a secret three-digit code. Only someone who can read repeated-digit clues and digit sums can crack it open!","teach":[{"title":"What is a repeated digit clue?","body":"In a 3-digit number, sometimes one digit is used twice, like in 2-2-5. A clue might tell you which digit repeats, and how the other digit relates to it — such as being the sum of the repeated pair.","visual":"🔁"},{"title":"Digit sum","body":"The 'digit sum' means adding up all the digits in a number. For 2-2-5, the digit sum is 2+2+5=9. Many puzzles ask for this final sum instead of the number itself.","visual":"➕"}],"questions":[{"kind":"numeric","prompt":"A ranger's code is a three-digit number. The digit 3 occurs twice, and the third digit equals the sum of the two 3's (3+3=6). What is the code's digit sum (add all three digits together)?","answer":12,"explain":"The repeated digit is 3, so 3+3=6 is the third digit. Adding all three digits: 3+3+6=12."},{"kind":"mcq","prompt":"In another code, the digit 4 occurs twice, and the third digit is the sum of the two 4's (4+4=8). What is the LARGEST possible three-digit number using these digits?","options":["844","448","488","484"],"answer":0,"explain":"The digits are 4, 4, and 8. To make the largest number, place the biggest digit first: 8, then 4, then 4, giving 844."},{"kind":"numeric","prompt":"A code has an odd digit repeated twice: the digit 5 occurs twice, and the third digit is the sum of the two 5's — but only the ONES digit of that sum can be used, since a single digit can't be more than 9. What is the third digit?","answer":0,"explain":"5+5=10. Since a single digit can only be 0-9, we keep just the ones digit of 10, which is 0."},{"kind":"mcq","prompt":"A ranger code has the digit 2 repeated twice, and the third digit is the sum of the two 2's (2+2=4). If the code is written with the third digit FIRST, followed by the two repeated digits, what is the code?","options":["224","422","442","242"],"answer":1,"explain":"The third digit is 4, written first, followed by the repeated digit 2 twice: 4-2-2 = 422."}]},{"id":"et2","title":"Counting Elephants and Tigers","icon":"🐘","kind":"lesson","story":"At dawn, herds of elephants, tigers, and leopards cross the river all at once. Help the watchtower crew add, subtract, and share the counts correctly on the ranger's count sheet.","teach":[{"title":"Counting in groups","body":"When animals move in herds or groups, you can find totals by adding up how many are in each group. Sometimes you need to find a missing group by subtracting what you know from a total.","visual":"🐘"},{"title":"Doubling and sharing","body":"If two groups have a 'twice as many' or 'shared equally' relationship, you can use multiplication or division to find the missing number once you know one group's size.","visual":"✖️"}],"questions":[{"kind":"numeric","prompt":"A herd of 8 elephants crosses the river, followed by a group of tigers that is 3 fewer than the elephants. How many tigers crossed?","answer":5,"explain":"3 fewer than 8 is 8-3=5, so 5 tigers crossed."},{"kind":"numeric","prompt":"The ranger counts 45 animals in total today: elephants, tigers, and leopards. If there were 20 elephants and 15 tigers, how many leopards were counted?","answer":10,"explain":"45 - 20 - 15 = 10, so 10 leopards were counted."},{"kind":"mcq","prompt":"A leopard family has twice as many cubs as a tiger family. The tiger family has 3 cubs. How many cubs does the leopard family have?","options":["6","4","3","9"],"answer":0,"explain":"Twice as many as 3 is 3 x 2 = 6."},{"kind":"numeric","prompt":"In the morning, 12 elephants were seen at the watering hole. By evening, 5 more elephants joined, but 4 elephants left for the forest. How many elephants remained at the watering hole?","answer":13,"explain":"12 + 5 - 4 = 13 elephants remained."}]},{"id":"et3","title":"Sorting the Spotted and Striped","icon":"🐆","kind":"lesson","story":"The park's field guide sorts animals by their features: stripes, spots, tusks, and more. Help the young naturalist sort the animal cards into the correct groups.","teach":[{"title":"Sorting by one property","body":"Classification means grouping things that share a property. For example, the group 'striped animals' would include tigers but not elephants, since only tigers have stripes.","visual":"🏷️"},{"title":"Sorting by two properties","body":"Sometimes a whole group is really two smaller groups added together, like tigers and leopards both counting as 'big cats.' Add the smaller groups to get the bigger group's total.","visual":"🔗"}],"questions":[{"kind":"mcq","prompt":"This week rangers logged 3 Elephants, 2 Tigers, 4 Leopards, and 1 Peacock. Which property group has the MOST animals: 'Has tusks' (elephants), 'Has stripes' (tigers), or 'Has spots' (leopards)?","options":["Has tusks (elephants)","They are all equal","Has stripes (tigers)","Has spots (leopards)"],"answer":3,"explain":"Leopards have spots and there are 4 of them — more than the 3 elephants (tusks) or 2 tigers (stripes)."},{"kind":"numeric","prompt":"Using the same log (3 Elephants, 2 Tigers, 4 Leopards, 1 Peacock), how many animals in total do NOT have tusks?","answer":7,"explain":"Only elephants have tusks (3 of them). The total is 3+2+4+1=10, so 10-3=7 animals have no tusks."},{"kind":"mcq","prompt":"A group of animals is sorted into 'Big Cats' (tigers and leopards) and 'Not Big Cats' (elephants and peacocks). Using the same log (3 Elephants, 2 Tigers, 4 Leopards, 1 Peacock), how many animals are Big Cats?","options":["4","3","10","6"],"answer":3,"explain":"Big Cats are tigers and leopards: 2 tigers + 4 leopards = 6."},{"kind":"numeric","prompt":"A ranger wants to sort 15 animal photos into two piles: 'Striped' and 'Not striped.' If 6 photos show striped animals, how many photos go in the 'Not striped' pile?","answer":9,"explain":"15 - 6 = 9 photos go in the 'Not striped' pile."}]},{"id":"et4","title":"Multi-Clue Jungle Mysteries","icon":"🕵️","kind":"lesson","story":"Three animal footprints were found near the river, but the muddy sign only gives clues, not names. Use every clue together to solve the mystery of the jungle trail.","teach":[{"title":"Combining clues","body":"When solving a mystery with several clues, use each clue to rule out wrong answers. The right answer must fit EVERY clue at once, not just one of them.","visual":"🧩"},{"title":"Process of elimination","body":"If you know who something ISN'T, you can cross that option off the list. Keep crossing off wrong choices until only one answer is left standing.","visual":"❌"}],"questions":[{"kind":"mcq","prompt":"Three animals — Elephant, Tiger, and Leopard — each left one footprint by the river. Clue 1: The Elephant's footprint is the biggest. Clue 2: The Leopard's footprint is smaller than the Tiger's. Which animal left the SMALLEST footprint?","options":["Elephant","Leopard","Cannot be determined","Tiger"],"answer":1,"explain":"The Elephant's print is biggest, and the Leopard's print is smaller than the Tiger's, so the order from biggest to smallest is Elephant, Tiger, Leopard. The Leopard has the smallest print."},{"kind":"mcq","prompt":"Four animals — Elephant, Tiger, Leopard, Peacock — crossed the river one after another, in positions 1st to 4th. Clue 1: The Peacock crossed first. Clue 2: The Elephant crossed right after the Tiger. Clue 3: The Leopard crossed last. In which position did the Tiger cross?","options":["3rd","1st","4th","2nd"],"answer":3,"explain":"Peacock is 1st and Leopard is 4th. Since the Elephant comes right after the Tiger, the Tiger must be 2nd and the Elephant 3rd."},{"kind":"numeric","prompt":"Three rangers each spotted a different number of leopards: Rina, Sam, and Tara. Clue 1: Rina spotted 4 more leopards than Sam. Clue 2: Sam spotted 3 leopards. Clue 3: Tara spotted twice as many as Rina. How many leopards did Tara spot?","answer":14,"explain":"Sam spotted 3. Rina spotted 4 more than Sam: 3+4=7. Tara spotted twice as many as Rina: 7x2=14."},{"kind":"mcq","prompt":"Three animals are hiding: one behind a rock, one in a bush, and one up a tree. Clue 1: The Tiger is not up the tree. Clue 2: The Elephant cannot fit in the bush or up the tree. Clue 3: The Leopard is not behind the rock. Where is the Leopard hiding?","options":["In the bush","Cannot be determined","Behind the rock","Up the tree"],"answer":3,"explain":"The Elephant must be behind the rock, since it can't fit in the bush or the tree. Since the Tiger isn't up the tree, the Tiger is in the bush, leaving the tree for the Leopard."}]},{"id":"et5","title":"Digit Detectives Deeper In","icon":"🔍","kind":"lesson","story":"Deep in the ranger station archive, old logbook numbers have digits that reverse, flip, and hide surprising patterns. Put on your detective hat and dig into the digits!","teach":[{"title":"Reversing digits","body":"To reverse a 3-digit number, swap the first and last digits and keep the middle one the same. For example, reversing 123 gives you 321.","visual":"🔄"},{"title":"When reversing changes nothing","body":"If a number reads the same forwards and backwards, like 373, reversing it gives back the SAME number, so the difference between them is 0. These special numbers are called palindromes.","visual":"🪞"}],"questions":[{"kind":"numeric","prompt":"A three-digit number is a palindrome — reversing its digits gives back the exact same number. What is the SMALLEST possible sum of its digits (the number cannot start with 0)?","answer":2,"explain":"The smallest palindrome is 101 (the first and last digits must match and can't be 0, so the least is 1, with middle digit 0). Its digit sum is 1+0+1=2."},{"kind":"mcq","prompt":"Reverse the number 462. What is the reversed number?","options":["246","462","624","264"],"answer":3,"explain":"To reverse 462, swap the first and last digits: 2-6-4 = 264."},{"kind":"numeric","prompt":"A three-digit number is 350. What is the difference between the number and its reverse (subtract the smaller from the bigger)?","answer":297,"explain":"Reversing 350 gives 053, which is just 53. The difference is 350 - 53 = 297."},{"kind":"mcq","prompt":"Which of these three-digit numbers is a palindrome (reads the same forwards and backwards)?","options":["676","678","786","687"],"answer":0,"explain":"676 reversed is still 676 — the first and last digits match (6 and 6), so it's a palindrome."}]},{"id":"et6","title":"The Watering Hole Count","icon":"💧","kind":"lesson","story":"Every animal at the watering hole must be sorted by TWO features at once for the ranger's big survey: diet and group size. Can you count them correctly?","teach":[{"title":"Two-way sorting","body":"Sometimes animals are sorted by two features at the same time, like 'plant-eater' and 'lives in a herd.' An animal can match one, both, or neither feature.","visual":"🗂️"},{"title":"Using totals to find missing groups","body":"If you know the total number of animals and how many belong to some groups, you can subtract to find how many belong to the remaining group.","visual":"🧮"}],"questions":[{"kind":"numeric","prompt":"At the watering hole, there are 20 animals in total. 12 are plant-eaters, and the rest are meat-eaters. How many meat-eaters are there?","answer":8,"explain":"20 - 12 = 8 meat-eaters."},{"kind":"mcq","prompt":"Of the 20 animals, 9 are plant-eaters that live in herds, and 3 more plant-eaters live alone. How many plant-eaters are there in total?","options":["20","3","12","9"],"answer":2,"explain":"Plant-eaters in herds (9) plus plant-eaters alone (3) makes 9+3=12 plant-eaters in total."},{"kind":"numeric","prompt":"11 meat-eaters visit the watering hole: some are tigers and some are leopards. There are 3 more leopards than tigers. How many leopards are there?","answer":7,"explain":"Two times the tiger count plus 3 more equals 11, so tigers = (11-3)/2 = 4, and leopards = 4+3 = 7."},{"kind":"mcq","prompt":"The full survey counts 20 animals: 12 plant-eaters and 8 meat-eaters. Among the meat-eaters, 5 are tigers. How many meat-eaters are leopards (every meat-eater here is either a tiger or a leopard)?","options":["5","8","3","12"],"answer":2,"explain":"There are 8 meat-eaters, and 5 are tigers, so the rest, 8-5=3, are leopards."}]},{"id":"et-boss","title":"Slynx and the Scrambled Records","icon":"🏆","kind":"boss","story":"A mysterious shadow-leopard named Slynx has scrambled every logbook, mixed up every sorted card, and smudged every digit in the ranger station. Solve the final round of puzzles to restore order to the jungle records and win the Ranger's Badge!","boss":{"name":"Slynx, the Shade-Leopard","taunt":"You'll never sniff out my tricks, little ranger — my spots are far too clever for you!"},"teach":[{"title":"Bring it all together","body":"This final challenge mixes digit codes, animal counts, sorting groups, and multi-clue mysteries. Take a breath, read every clue carefully, and solve each puzzle one step at a time, just like you practiced in every jungle lesson.","visual":"🏆"}],"questions":[{"kind":"numeric","prompt":"A code has the digit 6 repeated twice, and the third digit is the sum of the two 6's — but only the ONES digit of that sum can be used. What is the third digit?","answer":2,"explain":"6+6=12. Since a digit can only be 0-9, we keep the ones digit of 12, which is 2."},{"kind":"mcq","prompt":"A herd of 14 elephants is joined by 6 more, then 5 elephants wander off to the forest. How many elephants remain?","options":["9","19","14","15"],"answer":3,"explain":"14 + 6 - 5 = 15 elephants remain."},{"kind":"numeric","prompt":"The ranger's final log shows 5 Elephants, 3 Tigers, 6 Leopards, and 2 Peacocks. How many animals in total have neither stripes nor spots (that is, are not tigers or leopards)?","answer":7,"explain":"Only tigers (stripes) and leopards (spots) are excluded. That leaves 5 elephants + 2 peacocks = 7 animals with neither."},{"kind":"mcq","prompt":"Three friends — Ravi, Sana, and Tom — each photographed a different jungle animal: Elephant, Tiger, or Leopard. Clue 1: Ravi did not photograph the Tiger. Clue 2: Sana photographed the Leopard. Clue 3: Tom did not photograph the Elephant. Which animal did Tom photograph?","options":["Leopard","Elephant","Tiger","Cannot be determined"],"answer":2,"explain":"Sana already has the Leopard. Since Ravi didn't photograph the Tiger, Ravi must have the Elephant, leaving the Tiger for Tom."},{"kind":"numeric","prompt":"A three-digit number is 280. What is the difference between the number and its reverse?","answer":198,"explain":"Reversing 280 gives 082, which is 82. The difference is 280 - 82 = 198."},{"kind":"mcq","prompt":"At the final watering hole count, 18 animals total are sorted: 10 are plant-eaters, and the meat-eaters are split evenly between tigers and leopards. How many leopards are there?","options":["4","2","10","8"],"answer":0,"explain":"Meat-eaters = 18-10=8. Split evenly between tigers and leopards gives 8 divided by 2 = 4 leopards."},{"kind":"numeric","prompt":"A code has the digit 3 repeated twice, and the third digit is the sum of the two 3's (3+3=6). Arrange all three digits to make the SMALLEST possible three-digit number. What is that number?","answer":336,"explain":"The digits are 3, 3, and 6. For the smallest number, put the smallest digit first: 3, then 3, then 6, giving 336."}]}]},{"id":"funwithsymmetry4","index":10,"name":"Fun with Symmetry","subtitle":"Computational Thinking — Chapter 11","emoji":"🦋","palette":{"from":"#ec4899","to":"#831843"},"lessons":[{"id":"fs1","title":"The Mirror Path","icon":"🪞","kind":"lesson","story":"You step through a glowing gateway into the Mirror Woods, where every path splits into two matching halves. The gate guardian will only let you pass if you can spot true symmetry!","teach":[{"title":"What Is Symmetry?","body":"A shape has symmetry if you can fold it along a line so that both halves land exactly on top of each other, matching perfectly. Think of a butterfly wings, the left and right sides mirror each other.","visual":"🦋"},{"title":"The Line of Symmetry","body":"The imaginary fold line that splits a symmetric shape into two identical mirror halves is called a line of symmetry. Some shapes have one, some have many, and some have none at all.","visual":"✂️"}],"questions":[{"kind":"mcq","prompt":"Butterfly wings on the left and right look exactly alike, like a mirror. What is the special line down the middle called?","options":["Fold code","Line of numbers","Border line","Line of symmetry"],"answer":3,"explain":"The fold line where both halves match perfectly is called the line of symmetry."},{"kind":"mcq","prompt":"Which capital letter has a line of symmetry running straight down the middle (top to bottom), so its left and right halves match?","options":["M","P","L","F"],"answer":0,"explain":"M can be folded top-to-bottom so its left half lands exactly on its right half. F, L and P cannot."},{"kind":"numeric","prompt":"A square piece of paper can be folded exactly in half in different ways so the two halves always match perfectly. How many different lines of symmetry does a square have in total?","answer":4,"explain":"A square has 4 lines of symmetry: one through the middle of each pair of opposite sides, and one through each pair of opposite corners."},{"kind":"mcq","prompt":"Which shape below has NO line of symmetry at all?","options":["A scalene triangle (all three sides different lengths)","The letter A","A circle","A square"],"answer":0,"explain":"A scalene triangle has no equal sides or angles, so no fold line can ever make both halves match."}]},{"id":"fs2","title":"Fold the Paper","icon":"📄","kind":"lesson","story":"The Guardian of Folds hands you a stack of magic paper and a tiny hole-punch. Predict what appears when the paper unfolds, and the next chamber of the Mirror Woods will open for you.","teach":[{"title":"Folding and Cutting","body":"When you fold paper and then cut or punch a hole through it, the cut goes through every layer. When you unfold the paper, the hole appears on every part that was stacked together, mirrored across the fold line.","visual":"📄"},{"title":"Predicting the Unfold","body":"To imagine what a folded and cut paper will look like unfolded, picture the fold line as a mirror. Whatever shape you cut gets copied and flipped across that mirror line.","visual":"🔍"}],"questions":[{"kind":"mcq","prompt":"You fold a square paper exactly in half from left to right (like closing a book), then punch one hole near the top-right corner of the folded paper. When you unfold it, what do you see?","options":["2 holes, one on each half, mirrored across the fold","4 holes, one in each corner","No holes, the paper tears instead","1 hole in the very center"],"answer":0,"explain":"One fold makes two layers, so the punch goes through both and you see 2 mirrored holes after unfolding."},{"kind":"mcq","prompt":"A rectangular paper is folded in half from top to bottom. A small triangle notch is cut starting right on the folded edge (the fold line itself). When you unfold the paper, what will you see along the fold line?","options":["A diamond-shaped hole sitting exactly on the fold line","A triangle hole only on the top half","A square hole in one corner","Two separate triangle holes far apart"],"answer":0,"explain":"Cutting a notch on the fold makes each half a mirror of the other, so the two triangle halves join into one whole diamond shape when unfolded."},{"kind":"numeric","prompt":"You fold a paper strip in half, then fold it in half again, so it is folded twice (4 layers thick). You then cut a small circle out of a corner of the small folded packet, away from any fold line. When you fully unfold the paper, how many circles will you see?","answer":4,"explain":"Two folds create 4 layers of paper, so a single cut through the packet becomes 4 separate circles when unfolded."},{"kind":"mcq","prompt":"Which sentence best describes what happens when you unfold a paper that was folded once and had a shape cut starting from the fold?","options":["The paper becomes larger than before","The cut shape turns into three separate copies","The cut shape disappears completely","The cut shape becomes two mirror-image halves joined together at the fold, like a butterfly"],"answer":3,"explain":"A cut that starts on the fold becomes a whole symmetric shape when unfolded, made of two mirrored halves joined at the fold line."}]},{"id":"fs3","title":"Letter Symmetry Detectives","icon":"🔤","kind":"lesson","story":"A wall of glowing letters blocks your way. Only letters with the right kind of symmetry will light up and let you through, put on your detective hat and check each one carefully.","teach":[{"title":"Vertical vs Horizontal Symmetry","body":"A letter has vertical symmetry if folding it left-to-right (down an up-down line) makes the two halves match. It has horizontal symmetry if folding it top-to-bottom (across a side-to-side line) makes the two halves match. Some letters have both, some have only one, and some have neither.","visual":"🔤"},{"title":"Detective Examples","body":"The letter H has both vertical and horizontal symmetry, it matches when folded either way. The letter B only matches top-to-bottom (horizontal). The letter A only matches left-to-right (vertical). The letter N matches neither way!","visual":"🕵️"}],"questions":[{"kind":"mcq","prompt":"Which letter has a HORIZONTAL line of symmetry, meaning folding it top-to-bottom makes the top and bottom halves match?","options":["T","V","B","A"],"answer":2,"explain":"B looks the same on top and bottom when folded horizontally. A, T and V only match left-to-right, not top-to-bottom."},{"kind":"mcq","prompt":"Which of these letters does NOT have both vertical AND horizontal symmetry?","options":["O","N","H","X"],"answer":1,"explain":"N has no line of symmetry at all, while O, H and X all match both when folded top-to-bottom and left-to-right."},{"kind":"numeric","prompt":"Look at these letters: V, N, A, H, U, X, C, D, K. How many of them have a VERTICAL line of symmetry (matching when folded left-to-right)?","answer":5,"explain":"V, A, H, U and X all have vertical symmetry, that is 5 letters. N, C, D and K do not match when folded left-to-right."},{"kind":"mcq","prompt":"Priya writes the word MOM on a card and holds it up facing a flat mirror (a left-right flip). Which letters in MOM will look exactly the same in the mirror?","options":["All three letters (M, O, M)","Only the O","Only the two Ms","None of the letters"],"answer":0,"explain":"Both M and O have vertical lines of symmetry, so every letter in MOM looks unchanged in a left-right mirror."}]},{"id":"fs4","title":"Counting Fold Lines","icon":"🔺","kind":"lesson","story":"The Shape Keeper challenges you to count every hidden fold line in her collection of magical tiles. Get the counts right and she will lend you her enchanted ruler for the journey ahead.","teach":[{"title":"Counting All the Fold Lines","body":"Some shapes have just one line of symmetry, some have several, and some, like a circle, have so many that you could draw a line through the middle in any direction at all and it would still match!","visual":"🔺"},{"title":"A Handy Pattern","body":"For a regular shape where all sides and angles are equal, the number of lines of symmetry is usually the same as its number of sides. A regular (equal-sided) triangle has 3, a square has 4, and so on.","visual":"📐"}],"questions":[{"kind":"numeric","prompt":"An equilateral triangle (all 3 sides equal, all angles equal) can be folded along how many different lines so both halves always match exactly?","answer":3,"explain":"An equilateral triangle has 3 lines of symmetry, one running from each corner to the middle of the opposite side."},{"kind":"numeric","prompt":"A rectangle that is NOT a square (its long sides and short sides are different lengths) has how many lines of symmetry?","answer":2,"explain":"A non-square rectangle only matches when folded through the middle of its long sides or through the middle of its short sides, 2 lines in total."},{"kind":"numeric","prompt":"A regular hexagon (a shape with 6 equal sides) has how many lines of symmetry?","answer":6,"explain":"A regular hexagon has 6 lines of symmetry, matching its 6 equal sides."},{"kind":"mcq","prompt":"Which shape has SO MANY lines of symmetry that you could draw a fold line through its center in any direction at all and it would still match perfectly?","options":["A circle","A regular pentagon","A square","A rectangle"],"answer":0,"explain":"A circle looks exactly the same no matter which line you draw through its center, so it has countless lines of symmetry."}]},{"id":"fs5","title":"Mirror Digits","icon":"🔢","kind":"lesson","story":"In the Hall of Numbers, every digit is reflected in a still, silver pool. Some digits stay the same in the water, and some change completely. Read the reflections correctly to earn the golden key.","teach":[{"title":"Digits in a Mirror","body":"A flat mirror placed to the side of a digit flips it left-to-right. Some digits, like 0, 1 and 8, look exactly the same after this flip because they have a vertical line of symmetry. Others, like 2, 3, 5 and 7, look different or backwards.","visual":"🔢"},{"title":"Flipping a Whole Number","body":"When a mirror flips a whole number written left-to-right, it also reverses the order of the digits, in addition to flipping each digit itself. Numbers that read the same forwards and backwards, like 101, can end up looking unchanged.","visual":"🪞"}],"questions":[{"kind":"mcq","prompt":"Which digit looks EXACTLY the same when reflected in a mirror placed to its side (a left-right flip)?","options":["8","2","3","5"],"answer":0,"explain":"The digit 8 has a vertical line of symmetry, so it looks unchanged in a left-right mirror. 2, 3 and 5 do not."},{"kind":"mcq","prompt":"Reema holds up the number 101 to a flat mirror (a left-right flip). What does she see in the reflection?","options":["111","101 (exactly the same)","010","202"],"answer":1,"explain":"Both the digits 1 and 0 look the same in a mirror, and reading 101 backwards still gives 101, so the reflection is unchanged."},{"kind":"mcq","prompt":"Which of these digits does NOT have a vertical line of symmetry?","options":["1","0","2","8"],"answer":2,"explain":"The digit 2 looks different when flipped left-to-right, so it has no vertical line of symmetry. 0, 1 and 8 all do."},{"kind":"numeric","prompt":"Look at the digits 0, 1, 2, 3 and 8. How many of them have a vertical line of symmetry (look the same in a left-right mirror)?","answer":3,"explain":"Only 0, 1 and 8 look the same when flipped left-to-right, that is 3 digits. 2 and 3 look different."}]},{"id":"fs6","title":"Symmetry Patterns","icon":"🔁","kind":"lesson","story":"The final chamber before the tower holds a shimmering pattern wall that is missing pieces. Use symmetry to figure out exactly what belongs in each gap, and the tower door will finally open.","teach":[{"title":"Patterns That Mirror Themselves","body":"Some patterns, words, and sequences are symmetric around a middle point, just like shapes are. If you know one half of the pattern, you can mirror it to figure out the missing other half.","visual":"🔁"},{"title":"Palindromes","body":"A word or sequence that reads exactly the same forwards and backwards is called a palindrome, it is symmetric around its center, just like folding a shape in half.","visual":"📖"}],"questions":[{"kind":"mcq","prompt":"A row of shapes is symmetric around its middle: Star, Circle, Triangle, ?, Circle, Star. What shape must go in place of the ? to keep the row symmetric?","options":["Star","Triangle","Circle","Square"],"answer":1,"explain":"For the row to mirror itself around the middle, the two center shapes must match, so the missing shape must be a Triangle."},{"kind":"mcq","prompt":"The word LEVEL is a palindrome, it reads exactly the same forwards and backwards, like a mirror around its center. What is the middle letter of LEVEL?","options":["E","There is no middle letter","V","L"],"answer":2,"explain":"LEVEL has 5 letters, and the middle (3rd) letter is V, with E and L on each side matching like mirror images."},{"kind":"numeric","prompt":"A symmetric pattern of 9 dots is arranged in a row, mirrored perfectly around the middle (5th) dot. Not counting the middle dot itself, how many dots are on each side of it?","answer":4,"explain":"Removing the 1 middle dot from 9 leaves 8 dots, split evenly as 4 on each side of the mirror line."},{"kind":"mcq","prompt":"Which of these words is a palindrome (reads the same forwards and backwards)?","options":["MIRROR","ROBOT","ROTOR","SYMBOL"],"answer":2,"explain":"ROTOR spelled backwards is still ROTOR, so it is symmetric around its center letter. The others are not."}]},{"id":"fs-boss","title":"The Symmetry Sorcerer","icon":"🧙","kind":"boss","story":"At the top of the tower, the Symmetry Sorcerer swirls a cloak covered in mirrors and folded paper charms. Answer every trick correctly to prove you have truly mastered the magic of symmetry!","boss":{"name":"The Symmetry Sorcerer","taunt":"Fold your fears in half, little apprentice, only a true reflection can ever defeat me!"},"teach":[{"title":"Symmetry Round-Up","body":"You have learned to spot lines of symmetry, predict folded and unfolded paper, sort mirror-friendly letters and digits, and complete symmetric patterns. Now put it all together to defeat the Sorcerer!","visual":"🧙"}],"questions":[{"kind":"mcq","prompt":"The Symmetry Sorcerer holds up the letter W. Does W have a vertical line of symmetry?","options":["It only has horizontal symmetry","Yes, its left and right halves match when folded down the middle","No, it has no symmetry at all","Only when written in lowercase"],"answer":1,"explain":"W folds neatly left-to-right into two matching halves, so it has a vertical line of symmetry."},{"kind":"numeric","prompt":"The Sorcerer's magic square banner has how many lines of symmetry in total (through the middles of the sides and through the corners)?","answer":4,"explain":"A square always has 4 lines of symmetry: 2 through opposite side-midpoints and 2 through opposite corners."},{"kind":"mcq","prompt":"The Sorcerer folds a paper in half and cuts a heart shape starting exactly on the fold line. What happens when the paper is unfolded?","options":["A plain square hole appears instead","Two separate half-hearts appear far apart","Nothing appears, the cut vanishes","A full, whole heart shape appears, centered on the fold line"],"answer":3,"explain":"A cut that starts on the fold becomes two mirrored halves joined together, forming one whole symmetric heart."},{"kind":"mcq","prompt":"Which digit does NOT look the same in a mirror (it has no vertical line of symmetry)?","options":["1","0","7","8"],"answer":2,"explain":"The digit 7 looks different when flipped left-to-right, unlike 0, 1 and 8."},{"kind":"numeric","prompt":"Out of the letters E, F, G, H and I, how many have at least one line of symmetry (vertical or horizontal)?","answer":3,"explain":"E, H and I each have at least one line of symmetry, that is 3 letters. F and G have none."},{"kind":"mcq","prompt":"Which of these words is a palindrome, reading the same forwards and backwards?","options":["MADAM","MIRROR","SYMMETRY","FOLDED"],"answer":0,"explain":"MADAM spelled backwards is still MADAM, making it perfectly symmetric around its center letter."},{"kind":"mcq","prompt":"The Sorcerer's final trick: a circle, a square, and a scalene triangle are placed before you. Which one has the FEWEST lines of symmetry, in fact, zero?","options":["The circle","The scalene triangle","The square","They all have the same number"],"answer":1,"explain":"A scalene triangle has no equal sides, so no fold line can ever make its two halves match, it has zero lines of symmetry."}]}]},{"id":"tickingclocks4","index":11,"name":"Ticking Clocks and Turning Calendar","subtitle":"Computational Thinking — Chapter 12","emoji":"🕐","palette":{"from":"#818cf8","to":"#312e81"},"lessons":[{"id":"tc1","title":"The Clockwork Gate","icon":"⏰","kind":"lesson","story":"You step through a shimmering gate into a hall where every wall is covered in giant clock faces. A tiny mechanical owl blinks at you: 'Read my hands correctly, traveler, or the gears will never turn!'","teach":[{"title":"Two Ways to Tell Time","body":"Clocks can show time with moving hands (analog) or with numbers (digital). Both tell you exactly the same time, just in different ways.","visual":"🕐"},{"title":"Hour Hand and Minute Hand","body":"The short hand points to the hour, and the long hand points to the minutes. Each number on the clock face is 5 minutes apart from the next.","visual":"⏱️"},{"title":"AM and PM","body":"A full day has 24 hours, split into two 12-hour halves. AM runs from midnight to noon, and PM runs from noon to midnight.","visual":"🌞"}],"questions":[{"kind":"mcq","prompt":"On a clock, the short hour hand points exactly at the 7, and the long minute hand points exactly at the 12. What time does the clock show?","options":["7:00","7:12","12:00","12:07"],"answer":0,"explain":"When the minute hand is on 12, it is exactly on the hour, so the hour hand shows the time: 7:00."},{"kind":"mcq","prompt":"The minute hand of a clock points exactly to the 9. How many minutes past the hour is it?","options":["45 minutes","15 minutes","9 minutes","30 minutes"],"answer":0,"explain":"Each number on the clock face is 5 minutes, so the 9 means 9 x 5 = 45 minutes past the hour."},{"kind":"numeric","prompt":"Each number on a clock face is how many minutes apart from the next number?","answer":5,"explain":"There are 60 minutes and 12 numbers on a clock, and 60 divided by 12 is 5."},{"kind":"mcq","prompt":"It is 4 o'clock in the afternoon. Should this time be written with AM or PM?","options":["PM","AM","Neither","Both"],"answer":0,"explain":"Afternoon time falls after noon, so it is written with PM."},{"kind":"numeric","prompt":"How many hours are there in one full day, from midnight to the next midnight?","answer":24,"explain":"A day is split into 24 hours in total."}]},{"id":"tc2","title":"Racing the Rest Stop","icon":"⏱️","kind":"lesson","story":"Glowing runners zoom around a track that never stops moving. To pass through Racing the Rest Stop, you must work out exactly when each runner started and stopped.","teach":[{"title":"What Is Elapsed Time?","body":"Elapsed time is how much time passes between a start moment and an end moment. You find it by counting forward from the start to the end.","visual":"⏳"},{"title":"Carrying Over Minutes","body":"If adding minutes goes past 60, carry the extra over into the next hour, because 60 minutes make 1 hour.","visual":"➕"},{"title":"Working Backwards","body":"If you know when something ended and how long it took, subtract the duration from the end time to find the start time.","visual":"⏪"}],"questions":[{"kind":"numeric","prompt":"A puzzle contest starts at 2:40 PM and lasts 35 minutes. It ends at 3:__ PM. What number goes in the blank?","answer":15,"explain":"2:40 plus 35 minutes is 3:15, because 40 + 35 = 75 minutes, which is 1 hour 15 minutes."},{"kind":"mcq","prompt":"A movie starts at 6:50 PM and ends at 8:20 PM. How long is the movie?","options":["1 hour 40 minutes","1 hour 30 minutes","1 hour 20 minutes","2 hours 10 minutes"],"answer":1,"explain":"From 6:50 PM to 8:20 PM is 1 hour 30 minutes."},{"kind":"numeric","prompt":"Arjun studied from 4:15 PM to 5:00 PM. How many minutes did he study?","answer":45,"explain":"From 4:15 to 5:00 is 45 minutes."},{"kind":"mcq","prompt":"Priya finishes cooking at 5:15 PM. Cooking took her 50 minutes. At what time did she start?","options":["4:25 PM","4:05 PM","4:35 PM","4:15 PM"],"answer":0,"explain":"5:15 PM minus 50 minutes is 4:25 PM."},{"kind":"numeric","prompt":"A train journey starts at 9:45 AM and ends at 11:05 AM. How many minutes did the journey take?","answer":80,"explain":"From 9:45 AM to 11:05 AM is 1 hour 20 minutes, which is 80 minutes."}]},{"id":"tc3","title":"The Day-Chasing Puzzle","icon":"🔁","kind":"lesson","story":"A swirling week-wheel spins endlessly in front of you. A friendly parrot squawks riddles about Mondays and Fridays — answer wrong, and the wheel spins you right back to the start!","teach":[{"title":"Weeks Loop Forever","body":"There are 7 days in a week, and after Sunday the pattern starts over again at Monday. This is called a repeating cycle.","visual":"🔁"},{"title":"Counting Forward in Days","body":"To find a day in the future, count forward day by day through the week, wrapping back to Monday after Sunday.","visual":"➡️"},{"title":"Using Remainders","body":"For big numbers of days, divide by 7 and look at the remainder — that tells you how many extra steps to count from today.","visual":"➗"}],"questions":[{"kind":"mcq","prompt":"Today is Monday. What day of the week will it be in 7 days?","options":["Tuesday","Monday","Sunday","Saturday"],"answer":1,"explain":"7 days is exactly one full week, so the day of the week repeats: Monday again."},{"kind":"mcq","prompt":"Today is Monday. What day will it be 17 days from now?","options":["Wednesday","Tuesday","Friday","Thursday"],"answer":3,"explain":"17 divided by 7 leaves a remainder of 3. Counting 3 days forward from Monday gives Thursday."},{"kind":"numeric","prompt":"Today is Wednesday. What is the smallest number of days from now until it is Wednesday again?","answer":7,"explain":"A week has 7 days, so the same weekday returns after 7 days."},{"kind":"mcq","prompt":"Today is Friday. What day was it 10 days ago?","options":["Tuesday","Wednesday","Monday","Thursday"],"answer":0,"explain":"10 divided by 7 leaves a remainder of 3. Counting 3 days backward from Friday gives Tuesday."},{"kind":"mcq","prompt":"A shop closes every 9th day. Its first closure is on a Sunday. On what day of the week will its second closure fall?","options":["Tuesday","Wednesday","Monday","Sunday"],"answer":0,"explain":"9 divided by 7 leaves a remainder of 2. Counting 2 days forward from Sunday gives Tuesday."}]},{"id":"tc4","title":"The Calendar Trail","icon":"📅","kind":"lesson","story":"A stone path stretches ahead, each step carved with a date. The path-keeper warns that some months are longer than others, so you must count your steps just right to reach the end.","teach":[{"title":"How Long Is a Month?","body":"Most months have 30 or 31 days, but February usually has 28 days (29 in a leap year). Knowing this helps you count dates correctly.","visual":"📅"},{"title":"Rolling Into the Next Month","body":"If adding days takes you past the last date of a month, subtract the month's length and continue counting into the next month.","visual":"🔄"},{"title":"Same Weekday, One Week Apart","body":"Any date that is exactly 7, 14, or 21 days after another date falls on the very same day of the week.","visual":"🗓️"}],"questions":[{"kind":"numeric","prompt":"March has 31 days. If today is 25th March, what date will it be 4 days from now?","answer":29,"explain":"25 + 4 = 29, and March has enough days, so the date is the 29th of March."},{"kind":"mcq","prompt":"April has 30 days. If today is 28th April, what date will it be 5 days from now?","options":["3rd May","3rd April","2nd May","33rd April"],"answer":0,"explain":"28 + 5 = 33, but April only has 30 days, so 33 - 30 = 3, landing on 3rd May."},{"kind":"mcq","prompt":"1st February this year is a Sunday. What day of the week is 8th February?","options":["Tuesday","Sunday","Saturday","Monday"],"answer":1,"explain":"8th February is exactly 7 days after 1st February, so it falls on the same weekday: Sunday."},{"kind":"mcq","prompt":"Which of these months usually has only 28 days?","options":["February","April","September","June"],"answer":0,"explain":"February usually has 28 days, and 29 days in a leap year."},{"kind":"numeric","prompt":"A year has 12 months. If January is month number 1, what is the month number of November?","answer":11,"explain":"Counting January to November: January is 1, so November is the 11th month."}]},{"id":"tc5","title":"The Fair-Ground Schedule","icon":"🎡","kind":"lesson","story":"The fair bursts with music and lights, and four booths that each open only twice a day. To win a prize at the Fair-Ground Schedule, you must line up your visits in an order that follows every ringmaster's rule.","teach":[{"title":"Ordering Events","body":"Sequencing means arranging events in an order that follows given rules, such as 'before' and 'after'.","visual":"📋"},{"title":"One at a Time","body":"In many schedules you can only do one activity at a time, so you must choose an order that satisfies every rule at once.","visual":"🎯"},{"title":"Read Every Clue","body":"Each clue narrows down the possible orders. Check your final order against every single clue before deciding.","visual":"🔍"}],"questions":[{"kind":"mcq","prompt":"At a school fair, Game A must happen before Game B, and Game B must happen before Game C. Which order is correct?","options":["B, A, C","C, B, A","B, C, A","A, B, C"],"answer":3,"explain":"Following the rules in order gives A first, then B, then C."},{"kind":"mcq","prompt":"Four friends line up for a ride: Meena is first, and Kiran is right after Asha. Which order fits both clues?","options":["Asha, Kiran, Meena, Dev","Meena, Asha, Kiran, Dev","Dev, Meena, Asha, Kiran","Meena, Kiran, Asha, Dev"],"answer":1,"explain":"Meena must be first, and Kiran must come immediately after Asha, which only happens in Meena, Asha, Kiran, Dev."},{"kind":"mcq","prompt":"You must attend Event P before Event Q, and Event Q before Event R. You must also start with the earliest event of the day, Event S. Which schedule fits all the rules?","options":["S, P, Q, R","P, S, Q, R","S, Q, P, R","P, Q, S, R"],"answer":0,"explain":"S must come first, and then P, Q, R must follow in that order."},{"kind":"numeric","prompt":"A librarian shelves books in this order: fiction, science, history, art — 4 sections in total. She has just finished shelving science. How many sections does she still have left to shelve?","answer":2,"explain":"Fiction and science are done, leaving history and art, which is 2 sections."},{"kind":"mcq","prompt":"Three chores must be done in order: sweeping before mopping, and mopping before dusting. Which list is in the correct order?","options":["Dusting, Sweeping, Mopping","Sweeping, Mopping, Dusting","Mopping, Sweeping, Dusting","Mopping, Dusting, Sweeping"],"answer":1,"explain":"Sweeping must come first, then mopping, then dusting, exactly as the rules say."}]},{"id":"tc6","title":"Twin Candles and Tricky Timers","icon":"🕯️","kind":"lesson","story":"In a flickering hall, wax drips slowly as gears creak overhead. The keeper of Twin Candles and Tricky Timers challenges you with puzzles that mix clocks, calendars, and cycles all at once.","teach":[{"title":"Break It Into Steps","body":"Tricky time puzzles become easy when you solve them one small step at a time instead of all at once.","visual":"🧩"},{"title":"Work-and-Rest Cycles","body":"Patterns like 'work 5 days, then rest 1 day' repeat again and again. Find the length of one full cycle first.","visual":"🔁"},{"title":"Watch for Hidden Clues","body":"Some puzzles hide extra information, like a clock that runs fast. Read carefully so you don't miss it.","visual":"🔍"}],"questions":[{"kind":"numeric","prompt":"A worker works 5 days in a row, then rests on the 6th day. If he starts working on Day 1, on which day number is his 2nd rest day?","answer":12,"explain":"Each cycle is 6 days long (5 work + 1 rest), so the first rest is Day 6 and the second rest is Day 12."},{"kind":"mcq","prompt":"A worker works 5 days then rests 1 day, starting work on a Monday. On what day of the week is his first rest day?","options":["Monday","Saturday","Sunday","Friday"],"answer":1,"explain":"Working Monday through Friday is 5 days, so the rest day falls on Saturday."},{"kind":"numeric","prompt":"A candle takes 240 minutes to burn out completely, burning at a steady rate. After it has burned for 90 minutes, how many minutes of burning time are left?","answer":150,"explain":"240 minus 90 leaves 150 minutes of burning time."},{"kind":"mcq","prompt":"A clock is set correctly at 2:00 PM. It runs fast and gains 5 extra minutes every hour. After 3 real hours have passed, how many minutes fast will the clock be?","options":["5 minutes","15 minutes","10 minutes","20 minutes"],"answer":1,"explain":"5 extra minutes each hour for 3 hours is 5 x 3 = 15 minutes fast."},{"kind":"numeric","prompt":"Reema starts reading at 6:10 PM and reads for 25 minutes. Then she rests for 10 minutes before her next activity. At how many minutes past 6:00 PM does her next activity start? (For example, 6:45 PM would be answered as 45.)","answer":45,"explain":"6:10 plus 25 minutes of reading is 6:35, and adding 10 more minutes of rest gives 6:45, which is 45 minutes past 6:00."}]},{"id":"tc-boss","title":"The Clocktower Guardian","icon":"🗼","kind":"boss","story":"At the top of the tallest tower, Chronos the Clocktower Guardian waits, surrounded by spinning clock hands and floating calendar pages. Prove you have mastered time and calendar logic, or be trapped in an endless loop of ticking seconds!","teach":[{"title":"Everything You Learned","body":"Clocks, elapsed time, weekday cycles, calendars, and schedules all use the same idea: careful, step-by-step counting.","visual":"🗼"}],"boss":{"name":"Chronos, the Clocktower Guardian","taunt":"Tick, tock — can you out-count my endless calendar before time runs out?"},"questions":[{"kind":"mcq","prompt":"Today is Tuesday. What day of the week will it be 23 days from now?","options":["Wednesday","Thursday","Saturday","Friday"],"answer":1,"explain":"23 divided by 7 leaves a remainder of 2. Counting 2 days forward from Tuesday gives Thursday."},{"kind":"numeric","prompt":"A cooking class starts at 3:20 PM and lasts 55 minutes. It ends at 4:__ PM. What number goes in the blank?","answer":15,"explain":"3:20 plus 55 minutes is 4:15, because 20 + 55 = 75 minutes, which is 1 hour 15 minutes."},{"kind":"mcq","prompt":"May has 31 days. If today is 27th May, what date and month will it be 6 days from now?","options":["3rd June","2nd May","2nd June","1st June"],"answer":2,"explain":"27 + 6 = 33, but May only has 31 days, so 33 - 31 = 2, landing on 2nd June."},{"kind":"numeric","prompt":"How many minutes are there in 2 hours 15 minutes?","answer":135,"explain":"2 hours is 120 minutes, plus 15 minutes more makes 135 minutes."},{"kind":"mcq","prompt":"A guard's duty repeats every 4 days: on duty for 3 days, then rest for 1 day. If he starts duty on a Sunday, what day of the week is his first rest day?","options":["Wednesday","Monday","Thursday","Tuesday"],"answer":0,"explain":"Sunday, Monday, and Tuesday are the 3 duty days, so the rest day falls on Wednesday."},{"kind":"numeric","prompt":"A clock correctly shows 5:00 PM. It gains 4 extra minutes every hour. After 2 real hours, how many minutes fast will it be?","answer":8,"explain":"4 extra minutes each hour for 2 hours is 4 x 2 = 8 minutes fast."},{"kind":"mcq","prompt":"You must finish Task 1 before Task 2, and Task 2 before Task 3. Which order is correct?","options":["Task 3, Task 1, Task 2","Task 1, Task 2, Task 3","Task 2, Task 1, Task 3","Task 2, Task 3, Task 1"],"answer":1,"explain":"Following the rules step by step gives Task 1, then Task 2, then Task 3."}]}]},{"id":"transportmuseum4","index":12,"name":"The Transport Museum","subtitle":"Computational Thinking - Chapter 13","emoji":"🚂","palette":{"from":"#4ade80","to":"#14532d"},"lessons":[{"id":"tm1","title":"Signs That Say the Same Thing","icon":"🔄","kind":"lesson","story":"Welcome to the Transport Museum! The curator has just hung new information signs near each exhibit, but some signs say the very same thing in different words. Help sort out which signs truly match.","teach":[{"title":"Saying the same thing two ways","body":"If a train carries 4 times as many passengers as a bus, that is the SAME as saying the bus carries a quarter of what the train carries. Multiplying one way and dividing the other way can describe the exact same fact.","visual":"🔄"},{"title":"Spot the twin statement","body":"To check if two statements match, imagine real numbers. If a bus carries 10 and a train carries 40, then the train being 4 times the bus and the bus being a quarter of the train are both true at once - they are twins!","visual":"🔍"}],"questions":[{"kind":"mcq","prompt":"A truck can carry three times as many boxes as a car. Which statement means the SAME thing?","options":["The truck and car can carry the same number of boxes","The car can carry three times as many boxes as the truck","The truck can carry three fewer boxes than the car","The car can carry a third as many boxes as the truck"],"answer":3,"explain":"If the truck carries 3 times as many boxes as the car, then the car carries exactly one-third of what the truck carries."},{"kind":"mcq","prompt":"A ferry carries twice as many passengers as a boat. Which statement means the SAME thing?","options":["The ferry carries half as many passengers as the boat","The boat carries half as many passengers as the ferry","The boat carries twice as many passengers as the ferry","The ferry carries two more passengers than the boat"],"answer":1,"explain":"Twice as many going one way means half as many going the other way - they describe the same passengers."},{"kind":"mcq","prompt":"A train holds four times as many people as a bus. Which of these statements gives the SAME information?","options":["The train holds four fewer people than the bus","The bus holds a quarter of what the train holds","The bus holds four times as many people as the train","The bus is bigger than the train"],"answer":1,"explain":"Four times as many one way is the same fact as a quarter as many the other way round."},{"kind":"numeric","prompt":"A van carries five times as many parcels as a scooter (so the scooter carries a fifth of what the van carries). If the van carries 45 parcels, how many parcels does the scooter carry?","answer":9,"explain":"A fifth of the van's parcels is 45 divided by 5, which equals 9, so the scooter carries 9 parcels."}]},{"id":"tm2","title":"Multiples on the Move","icon":"✖️","kind":"lesson","story":"The museum's model railway room is buzzing with visitors. To restock the gift shop and repair carts, you must work out exact passenger and cargo numbers using the times-as-many clues on each exhibit label.","teach":[{"title":"Multiply to find the bigger number","body":"If you know the SMALLER vehicle's number and how many times bigger the other one is, multiply to find the bigger vehicle's number. For example, bus times 4 equals train.","visual":"✖️"},{"title":"Divide to find the smaller number","body":"If you know the BIGGER vehicle's number and how many times bigger it is, divide to find the smaller vehicle's number. For example, train divided by 4 equals bus.","visual":"➗"}],"questions":[{"kind":"numeric","prompt":"A train carries 4 times as many passengers as a bus. If the bus carries 30 passengers, how many does the train carry?","answer":120,"explain":"30 times 4 is 120, so the train carries 120 passengers."},{"kind":"numeric","prompt":"A cargo ship carries 6 times as many containers as a truck. If the ship carries 240 containers, how many does the truck carry?","answer":40,"explain":"240 divided by 6 is 40, so the truck carries 40 containers."},{"kind":"mcq","prompt":"An airplane carries 3 times as many passengers as a coach bus. The coach bus carries 60 passengers. How many passengers does the airplane carry?","options":["63","240","180","20"],"answer":2,"explain":"60 times 3 is 180, so the airplane carries 180 passengers."},{"kind":"numeric","prompt":"A tram carries half as many passengers as a train. The train carries 90 passengers. How many passengers does the tram carry?","answer":45,"explain":"Half of 90 is 45, so the tram carries 45 passengers."}]},{"id":"tm3","title":"Comparison Chains","icon":"📏","kind":"lesson","story":"In the History of Wheels hall, model vehicles are lined up from smallest to biggest, but the name labels have fallen off! Use the comparison clues to work out which model sits where.","teach":[{"title":"Lining up by size","body":"Clues like carries more than and carries fewer than let you line vehicles up from least to most, like beads on a string. Draw the order out step by step so you do not lose track.","visual":"🔗"},{"title":"Filling in the middle","body":"Once you know the order, use any known numbers at the ends to work out what the middle value could be - it must be bigger than the smaller end and smaller than the bigger end.","visual":"🎯"}],"questions":[{"kind":"mcq","prompt":"The car carries fewer passengers than the van. The van carries fewer passengers than the bus. Which vehicle carries the MOST passengers?","options":["Car","Bus","Van","Cannot be determined"],"answer":1,"explain":"Following the chain car less than van less than bus, the bus carries the most passengers."},{"kind":"mcq","prompt":"Three vehicles carry 8, 15, and 25 passengers in some order. Clue 1: the Jeep carries the fewest. Clue 2: the Minibus carries more than the Jeep but fewer than the Coach. How many passengers does the Minibus carry?","options":["25","Cannot be determined","15","8"],"answer":2,"explain":"The Jeep has the fewest (8) and the Coach must be the most (25), so the Minibus, in between, has 15."},{"kind":"numeric","prompt":"A cycle-rickshaw carries 2 passengers. An auto-rickshaw carries 3 more passengers than the cycle-rickshaw. A tempo carries 2 times as many passengers as the auto-rickshaw. How many passengers does the tempo carry?","answer":10,"explain":"The auto-rickshaw carries 2 plus 3, which is 5 passengers, and the tempo carries 5 times 2, which is 10 passengers."},{"kind":"mcq","prompt":"Four vehicles are ordered from FEWEST to MOST passengers: Scooter, Car, Van, Bus. Which of these is TRUE?","options":["The Scooter carries more passengers than the Van","The Bus carries more passengers than the Car","The Van carries fewer passengers than the Scooter","The Car carries the most passengers"],"answer":1,"explain":"Since the order is Scooter, Car, Van, Bus from fewest to most, the Bus carries more than the Car (and everyone else)."}]},{"id":"tm4","title":"Half, Double and Quarter","icon":"➗","kind":"lesson","story":"The museum's newest exhibit compares old and new vehicles side by side - some carry double, some carry half, some carry just a quarter. Help the tour guide explain exactly how the numbers connect.","teach":[{"title":"Doubling and halving","body":"Double means multiply by 2. Half as many means divide by 2. These two words are opposites that describe the same pair of numbers from different directions.","visual":"⚖️"},{"title":"Thirds and quarters","body":"A third as many means divide by 3. A quarter as many means divide by 4. Watch out - these small words change the whole answer, so read carefully before you calculate!","visual":"🧮"}],"questions":[{"kind":"numeric","prompt":"A double-decker bus carries double the passengers of a single-decker bus. The single-decker carries 35 passengers. How many does the double-decker carry?","answer":70,"explain":"Double of 35 is 35 times 2, which equals 70, so the double-decker carries 70 passengers."},{"kind":"numeric","prompt":"A goods train carries a third as many cargo units as a mega train. The mega train carries 90 cargo units. How many cargo units does the goods train carry?","answer":30,"explain":"A third of 90 is 90 divided by 3, which equals 30, so the goods train carries 30 cargo units."},{"kind":"mcq","prompt":"A mini-van carries a quarter as many passengers as a full-size bus. The bus carries 48 passengers. How many passengers does the mini-van carry?","options":["24","192","12","4"],"answer":2,"explain":"A quarter of 48 is 48 divided by 4, which equals 12, so the mini-van carries 12 passengers."},{"kind":"numeric","prompt":"A speedboat carries half as many people as a ferry, and the ferry carries 3 times as many people as a canoe. The canoe carries 8 people. How many people does the speedboat carry?","answer":12,"explain":"The ferry carries 8 times 3, which is 24 people, and the speedboat carries half of that, 24 divided by 2, which is 12."}]},{"id":"tm5","title":"Mixed-Up Clues","icon":"🧭","kind":"lesson","story":"A mix-up in the workshop left extra clues scattered everywhere - and some of them are not even useful! Sort out what matters and solve the trickiest vehicle puzzles yet.","teach":[{"title":"Combine clues step by step","body":"Big puzzles feel easier if you solve them one clue at a time, writing down what you have figured out before moving to the next clue. Do not try to do it all in your head at once!","visual":"🧩"},{"title":"Ignore clues you do not need","body":"Not every clue in a puzzle is needed to answer the question. Before you calculate, ask yourself if this piece of information actually helps you find the answer. If not, set it aside.","visual":"🚧"}],"questions":[{"kind":"mcq","prompt":"A car park has 3 times as many cars as buses. There are 12 buses. Which statement is TRUE?","options":["There are 15 cars","There are 12 cars","There are 36 cars","There are 4 cars"],"answer":2,"explain":"12 times 3 is 36, so there are 36 cars."},{"kind":"numeric","prompt":"A station has trains, buses and autos. There are 5 times as many autos as buses. There are 8 buses. There are also 10 more trains than buses (though that clue is not needed here). How many autos are there?","answer":40,"explain":"8 times 5 is 40 autos. The clue about trains was extra information not needed to answer this question."},{"kind":"mcq","prompt":"To find how many wheels ALL the cars in a parking lot have altogether, which piece of information is NOT needed?","options":["Whether all cars have the same number of wheels","The number of wheels on one car","The colour of each car","The number of cars in the lot"],"answer":2,"explain":"The colour of a car has nothing to do with counting wheels, so it is not needed to solve the puzzle."},{"kind":"numeric","prompt":"A tempo carries fewer passengers than a van, and a van carries fewer passengers than a bus. The bus carries 50 passengers, which is 2 times as many as the van. The van carries 5 more passengers than the tempo. How many passengers does the tempo carry?","answer":20,"explain":"The van carries 50 divided by 2, which is 25 passengers. Since the van carries 5 more than the tempo, the tempo carries 25 minus 5, which is 20 passengers."}]},{"id":"tm6","title":"Ticket Booth Word Problems","icon":"🎟️","kind":"lesson","story":"It's opening day at the Transport Museum ticket booths! Visitors are lining up, and you must use ratios and totals to make sure every ticket and every seat is accounted for.","teach":[{"title":"Totals from ratios","body":"If you know the TOTAL of two vehicles' passengers and how many times bigger one is than the other, you can split the total into equal parts to find each amount - just like sharing carefully.","visual":"🎟️"},{"title":"Checking every part of a statement","body":"Some questions list several small facts and ask if they are all true together. Work out the real number first, then check each fact against it one at a time.","visual":"✅"}],"questions":[{"kind":"numeric","prompt":"A car carries 4 passengers, and a van carries 3 times as many passengers as a car. Together, how many passengers do the car and the van carry?","answer":16,"explain":"The van carries 4 times 3, which is 12 passengers. Together the car and van carry 4 plus 12, which is 16 passengers."},{"kind":"mcq","prompt":"A bus and a train together carry 100 passengers. The train carries 4 times as many passengers as the bus. How many passengers does the bus carry?","options":["25","4","20","80"],"answer":2,"explain":"The bus plus 4 times the bus makes 5 equal parts totalling 100, so one part (the bus) is 100 divided by 5, which is 20."},{"kind":"numeric","prompt":"A truck and a trailer together carry 60 boxes. The trailer carries 2 times as many boxes as the truck. How many boxes does the trailer carry?","answer":40,"explain":"The truck plus 2 times the truck makes 3 equal parts totalling 60, so the truck carries 60 divided by 3, which is 20 boxes, and the trailer carries 20 times 2, which is 40 boxes."},{"kind":"mcq","prompt":"150 seats are shared equally among 3 train coaches, A, B and C. Which of these statements is TRUE?","options":["All of these","Coach A has more than 40 seats","Coach B has exactly 50 seats","Coach C has fewer than 60 seats"],"answer":0,"explain":"150 divided by 3 is 50 seats in each coach. Since 50 is more than 40, exactly 50, and fewer than 60, all three statements are true at once."}]},{"id":"tm-boss","title":"The Grand Transport Challenge","icon":"🏆","kind":"boss","story":"Grinder Gus, the Ratio Wrecker, has jammed the museum's control room with a jumble of vehicle puzzles! Solve every one to fix the gears and reopen the Transport Museum for good.","boss":{"name":"Grinder Gus, the Ratio Wrecker","taunt":"Ha! My gears are twice as tricky as any bus timetable you have ever seen!"},"teach":[{"title":"Bring it all together","body":"This final challenge mixes equivalent statements, multiples, comparison chains, and total-plus-ratio puzzles. Take each question one step at a time, just like you practiced in every museum hall.","visual":"🏆"}],"questions":[{"kind":"mcq","prompt":"A cargo plane carries five times as many parcels as a delivery van. Which statement means the SAME thing?","options":["The plane carries a fifth as many parcels as the van","The van and plane carry the same number of parcels","The van carries five times as many parcels as the plane","The van carries a fifth as many parcels as the plane"],"answer":3,"explain":"Five times as many one way is the same fact as a fifth as many the other way round."},{"kind":"numeric","prompt":"A ferry carries 7 times as many passengers as a small boat. The boat carries 12 passengers. How many passengers does the ferry carry?","answer":84,"explain":"12 times 7 is 84, so the ferry carries 84 passengers."},{"kind":"numeric","prompt":"A container ship carries 9 times as many containers as a barge. The ship carries 108 containers. How many containers does the barge carry?","answer":12,"explain":"108 divided by 9 is 12, so the barge carries 12 containers."},{"kind":"mcq","prompt":"A cycle carries fewer passengers than a rickshaw, and the rickshaw carries fewer passengers than a car. The cycle carries 1 passenger and the car carries 4 passengers. Which is a possible number of passengers for the rickshaw?","options":["1","4","5","2"],"answer":3,"explain":"The rickshaw must carry more than 1 (the cycle) and fewer than 4 (the car). Only 2 fits between those two numbers."},{"kind":"numeric","prompt":"A speedboat carries half as many people as a ferry, and the ferry carries 3 times as many people as a canoe. The canoe carries 8 people. How many people does the speedboat carry?","answer":12,"explain":"The ferry carries 8 times 3, which is 24 people, and the speedboat carries half of that, 24 divided by 2, which is 12."},{"kind":"numeric","prompt":"A bus and a minibus together carry 80 passengers. The bus carries 3 times as many passengers as the minibus. How many passengers does the minibus carry?","answer":20,"explain":"The minibus plus 3 times the minibus makes 4 equal parts totalling 80, so the minibus carries 80 divided by 4, which is 20 passengers."},{"kind":"mcq","prompt":"200 tickets are shared equally among 4 ticket gates at the museum. Which of these statements is TRUE?","options":["All of these","Gate 1 sold more than 30 tickets","Gate 2 sold exactly 50 tickets","Gate 3 sold fewer than 70 tickets"],"answer":0,"explain":"200 divided by 4 is 50 tickets at each gate. Since 50 is more than 30, exactly 50, and fewer than 70, all three statements are true at once."}]}]},{"id":"datahandling4","index":13,"name":"Data Handling","subtitle":"Computational Thinking — Chapter 14","emoji":"📊","palette":{"from":"#fb7185","to":"#881337"},"lessons":[{"id":"dh1","title":"The Scorekeeper's Riddle","icon":"📝","kind":"lesson","story":"You step into the Hall of Records, where an old Scorekeeper guards enchanted scrolls of quiz scores. The ink has smudged some numbers — you must work out the missing marks before the gate will creak open.","teach":[{"title":"Rows and Columns","body":"A data table organizes facts in rows (across) and columns (up and down) — like a friend's name in one row and their score next to it. Reading one row at a time helps you find exactly the fact you need.","visual":"🗂️"},{"title":"Marks for Right and Wrong","body":"In many quizzes you gain marks for correct answers and lose marks for wrong ones. If you know some totals, you can work backwards, like a detective, to find the missing numbers.","visual":"🧮"}],"questions":[{"kind":"numeric","prompt":"In the Hall of Records, every CORRECT answer earns 5 marks and every WRONG answer loses 2 marks. Arjun answered 12 questions in total: 9 were correct and 3 were wrong. What was Arjun's total score?","answer":39,"explain":"9 correct x 5 = 45. 3 wrong x 2 = 6. So 45 - 6 = 39."},{"kind":"numeric","prompt":"Using the same rule (+5 for correct, -2 for wrong), Priya answered 10 questions in total and scored 36 marks. How many questions did she get correct?","answer":8,"explain":"If 8 are correct and 2 are wrong: 8x5=40, 2x2=4, and 40-4=36. So 8 were correct."},{"kind":"numeric","prompt":"Karan used the same rule (+5 correct, -2 wrong). He got 13 questions correct and scored 61 marks in total. How many questions did he get wrong?","answer":2,"explain":"13 correct answers give 13x5=65 marks. He only has 61, so he lost 4 marks. 4 divided by 2 (marks lost per wrong answer) is 2 wrong answers."},{"kind":"mcq","prompt":"Two friends used the same marking rule (+5 correct, -2 wrong). Neha got 10 correct and 0 wrong. Vikram got 9 correct and 1 wrong. Who scored higher, and by how many marks?","options":["Neha, by 7 marks","Vikram, by 7 marks","Both scored the same","Neha, by 5 marks"],"answer":0,"explain":"Neha: 10x5=50. Vikram: 9x5-2=43. 50-43=7, so Neha scored 7 marks higher."}]},{"id":"dh2","title":"Four Friends, Four Subjects","icon":"🗂️","kind":"lesson","story":"Floating scrolls list the marks of four friends — Aisha, Ben, Chloe, and Dev — across four subjects. The next door only opens once you can compare their scores correctly.","teach":[{"title":"Comparing Across a Table","body":"When you compare people in a table, look at one column (like one subject) at a time, and note who has the highest or lowest number in that column.","visual":"📊"},{"title":"Counting Matches","body":"Sometimes you need to count how many times something happens, like how many subjects one person beat another in, by checking each column one by one.","visual":"✅"}],"questions":[{"kind":"mcq","prompt":"In Math, Aisha scored 8, Ben scored 6, Chloe scored 7, and Dev scored 9. Who scored the highest in Math?","options":["Dev","Aisha","Chloe","Ben"],"answer":0,"explain":"9 is the highest of the four Math scores, and that belongs to Dev."},{"kind":"numeric","prompt":"In Science, Aisha scored 9, Ben scored 5, Chloe scored 6, and Dev scored 8. What is the difference between the highest and lowest Science score?","answer":4,"explain":"The highest is 9 (Aisha) and the lowest is 5 (Ben). 9 - 5 = 4."},{"kind":"mcq","prompt":"Here are the marks of three friends across four subjects:\nMath: Aisha 8, Ben 6, Chloe 7\nEnglish: Aisha 7, Ben 9, Chloe 8\nScience: Aisha 9, Ben 5, Chloe 6\nArt: Aisha 6, Ben 8, Chloe 9\nIn how many subjects did Chloe score MORE than Ben but LESS than Aisha?","options":["2","1","0","3"],"answer":0,"explain":"Math: Ben6 < Chloe7 < Aisha8, yes. Science: Ben5 < Chloe6 < Aisha9, yes. English and Art do not fit. That makes 2 subjects."},{"kind":"numeric","prompt":"Dev's marks were Math 9, English 6, Science 8, and Art 7. What is Dev's total score across all four subjects?","answer":30,"explain":"9 + 6 + 8 + 7 = 30."}]},{"id":"dh3","title":"Tally Ho! Counting the Crowd","icon":"✋","kind":"lesson","story":"At the Fairground of Numeria, the counting-keeper has lost track of visitors and tally sticks lie scattered everywhere. Help count the tallies and read the frequency charts to calm the fairground down.","teach":[{"title":"Tally Marks","body":"Tally marks are a quick way to count: one line for each item, and the fifth line is drawn across the first four to make a bundle of 5. Bundles of 5 make counting large groups fast.","visual":"✋"},{"title":"Frequency Tables","body":"A frequency table shows how many times each thing was counted, so you can quickly compare which item appears the most or the least.","visual":"📋"}],"questions":[{"kind":"numeric","prompt":"At the fruit stall, the tally for apples showed 4 full bundles of 5 plus 3 extra marks. How many apples were counted in total?","answer":23,"explain":"4 bundles of 5 make 20, plus 3 more makes 23."},{"kind":"numeric","prompt":"In a survey of 30 classmates' favourite fruit, the frequency table showed: Apples 8, Bananas 11, Mangoes 6, and the rest liked Strawberries. How many classmates liked Strawberries?","answer":5,"explain":"8 + 11 + 6 = 25 classmates are already counted. 30 - 25 = 5 liked Strawberries."},{"kind":"mcq","prompt":"A tally of pets owned by students showed: Dogs 6, Cats 9, Fish 4, and Birds 7. Which pet was the LEAST common?","options":["Birds","Cats","Dogs","Fish"],"answer":3,"explain":"4 is the smallest tally, and that belongs to Fish."},{"kind":"numeric","prompt":"Using the same pet tally (Dogs 6, Cats 9, Fish 4, Birds 7), how many MORE students chose Cats than Fish?","answer":5,"explain":"9 - 4 = 5."},{"kind":"mcq","prompt":"In tally marks, a bundle where four straight lines are crossed by a fifth diagonal line stands for how many?","options":["5","1","4","10"],"answer":0,"explain":"Each bundle of tally marks, four lines plus one crossing line, always stands for 5."}]},{"id":"dh4","title":"Two of a Kind","icon":"➗","kind":"lesson","story":"The Twin Halls will only open for someone who can split a crowd into overlapping groups and share leftovers fairly. Time to prove you can handle data that counts things TWICE.","teach":[{"title":"Counting 'Both'","body":"When data shows how many people like TWO different things, some people get counted in both groups. Careful subtraction helps you find who likes only one thing, or truly both.","visual":"🔀"},{"title":"Sharing Equally","body":"To share a total equally among a group, first add up everything, then divide by how many people or groups will share it.","visual":"➗"}],"questions":[{"kind":"numeric","prompt":"In a survey of 20 children, 12 like Cricket, 9 like Football, and 5 like BOTH games. How many children like ONLY Cricket (not Football)?","answer":7,"explain":"5 of the 12 Cricket fans also like Football, so 12 - 5 = 7 like only Cricket."},{"kind":"numeric","prompt":"Using the same survey (12 like Cricket, 9 like Football, 5 like both, 20 children in total), how many children like NEITHER game?","answer":4,"explain":"Children who like at least one game: 12 + 9 - 5 = 16. So 20 - 16 = 4 like neither."},{"kind":"mcq","prompt":"Four friends have pencils: Vidya has 6, Om has 9, Kiran has 7, and Rita has 12. Which two friends' pencils, if combined, can be shared EQUALLY among 5 people?","options":["Om and Rita","Kiran and Rita","Vidya and Kiran","Vidya and Om"],"answer":3,"explain":"6 + 9 = 15, and 15 shared among 5 people gives exactly 3 each. No other pair adds up to a multiple of 5."},{"kind":"numeric","prompt":"In a survey of 25 students, 14 like Basketball, 10 like Swimming, and 3 like BOTH sports. How many students like NEITHER sport?","answer":4,"explain":"Students who like at least one sport: 14 + 10 - 3 = 21. So 25 - 21 = 4 like neither."}]},{"id":"dh5","title":"The Pattern of Sales","icon":"📈","kind":"lesson","story":"The Trade Ledger room shows a magical shop's sales carved into stone, growing by the same amount every week. Predict the missing numbers correctly to unlock the vault.","teach":[{"title":"Spotting a Pattern in Data","body":"Sometimes data follows a pattern, like a number growing by the same amount every time. Once you spot the pattern, you can predict future values without waiting to see them.","visual":"📈"},{"title":"Adding Up Totals","body":"To find a total over many time periods, like a whole year, add up the values for each period one at a time, or use the pattern to work them out quickly.","visual":"➕"}],"questions":[{"kind":"numeric","prompt":"A bakery sold 20 cakes in Week 1, and sales increased by 5 cakes every week after that. How many cakes did it sell in Week 4?","answer":35,"explain":"Week 1: 20, Week 2: 25, Week 3: 30, Week 4: 35."},{"kind":"numeric","prompt":"Using the same pattern (20 cakes in Week 1, +5 cakes each week), what is the TOTAL number of cakes sold over the first 4 weeks?","answer":110,"explain":"20 + 25 + 30 + 35 = 110."},{"kind":"numeric","prompt":"A toy shop's sales pattern for 6 months was: 12, 18, 24, 30, 36, 42 (each month 6 more than the last). How many units were sold in total over these 6 months?","answer":162,"explain":"12 + 18 + 24 + 30 + 36 + 42 = 162."},{"kind":"mcq","prompt":"A pattern of book sales is: 100, 90, 80, 70... If this pattern continues, how many books were sold in the 6th month?","options":["50","60","100","40"],"answer":0,"explain":"The pattern drops by 10 each month: 100, 90, 80, 70, 60, 50. The 6th month is 50."}]},{"id":"dh6","title":"Clues in the Records","icon":"🕵️","kind":"lesson","story":"In the final chamber before the vault, scrolls of clues swirl around you. Only a true Data Detective can eliminate the wrong answers, one clue at a time, and find what truly fits.","teach":[{"title":"Elimination","body":"When a clue rules something OUT, cross it off your list of possibilities. Whatever is left standing after all the clues must be the answer.","visual":"🕵️"},{"title":"Combining Clues","body":"Sometimes one clue is not enough. You must combine several clues together, step by step, to find the one answer that fits every single one.","visual":"🧩"}],"questions":[{"kind":"mcq","prompt":"I was NOT born on Monday, Wednesday, or Friday. My friend was NOT born on Tuesday, Thursday, or Sunday. If we were both born on the same day, which day was it?","options":["Thursday","Sunday","Saturday","Tuesday"],"answer":2,"explain":"My possible days are Sunday, Tuesday, Thursday, Saturday. My friend's possible days are Monday, Wednesday, Friday, Saturday. The only day in both lists is Saturday."},{"kind":"mcq","prompt":"Each shop sells two fruits out of Apples, Bananas, Mangoes, and Strawberries — the fruits on DISPLAY are the ones the shop does NOT sell. Shop A displays Apples and Bananas (so it sells Mangoes and Strawberries). Shop B displays Mangoes and Apples (so it sells Bananas and Strawberries). Priya buys everything Shop A sells, and Rohit buys everything Shop B sells. Which fruit did both of them buy?","options":["Bananas","Strawberries","Apples","Mangoes"],"answer":1,"explain":"Shop A sells Mangoes and Strawberries. Shop B sells Bananas and Strawberries. The only fruit in both lists is Strawberries."},{"kind":"mcq","prompt":"Four buildings have pet rules based on height. Sunrise Tower (tallest) does not allow Dogs. Oakwood Heights (2nd tallest) does not allow Cats. Bell Cottage (shortest) does not allow Rabbits. Maple Court (in between) has no pet rule at all. Leela owns a Dog, a Cat, and a Rabbit. Which building can she live in with all three pets?","options":["Sunrise Tower","Bell Cottage","Maple Court","Oakwood Heights"],"answer":2,"explain":"Every other building bans one of Leela's pets. Only Maple Court has no rule, so all three pets are allowed there."},{"kind":"mcq","prompt":"A cat, a dog, a parrot, and a goldfish belong to four kids: Ira, Om, Zoya, and Kabir.\nClue 1: Om is best friends with the cat's owner (so Om does NOT own the cat).\nClue 2: The dog belongs to Zoya.\nClue 3: Ira is not the cat's owner.\nWho owns the cat?","options":["Ira","Om","Zoya","Kabir"],"answer":3,"explain":"Zoya owns the dog, and the clues rule out Om and Ira for the cat. That leaves Kabir as the cat's owner."}]},{"id":"dh-boss","title":"The Grand Auditor","icon":"🧾","kind":"boss","story":"At the top of the Hall of Records, the Grand Auditor blocks the final seal of Class 4 — a floating wall of scrolls, tallies, and clues, all mixed together. Solve every kind of data challenge to prove you're a true Data Detective before the gate to Class 5 opens.","teach":[{"title":"You're a Data Detective Now","body":"You've learned to read tables, count with tallies, spot patterns, share things equally, and use clues to eliminate wrong answers. The Grand Auditor will test ALL of these skills together — stay sharp!","visual":"🎯"}],"boss":{"name":"The Grand Auditor","taunt":"I've weighed a thousand tables and tallied a million marks — let's see if your data skills are sharp enough to close the final chapter of Class 4!"},"questions":[{"kind":"numeric","prompt":"In the final trial, correct answers earn 4 marks and wrong answers lose 1 mark. Zara answered 20 questions: 15 correct and 5 wrong. What was her total score?","answer":55,"explain":"15 x 4 = 60. 5 x 1 = 5. 60 - 5 = 55."},{"kind":"numeric","prompt":"Using the same rule (+4 correct, -1 wrong), Yusuf got 14 questions correct and scored 51 marks in total. How many did he get wrong?","answer":5,"explain":"14 correct answers give 14x4=56 marks. He only has 51, so he lost 5 marks, which means 5 wrong answers."},{"kind":"mcq","prompt":"Marks in a final quiz were: Math — Sam 9, Tia 7. Science — Sam 6, Tia 8. In how many subjects did Tia score HIGHER than Sam?","options":["3","2","0","1"],"answer":3,"explain":"In Math, Sam (9) beats Tia (7). In Science, Tia (8) beats Sam (6). That is 1 subject where Tia scored higher."},{"kind":"numeric","prompt":"The tally of visitors to the Hall this week was: Monday 8, Tuesday 12, Wednesday 6, Thursday 9, Friday 15. What is the TOTAL number of visitors for the week?","answer":50,"explain":"8 + 12 + 6 + 9 + 15 = 50."},{"kind":"numeric","prompt":"Of 30 students in the final class, 18 like Puzzles, 14 like Riddles, and 7 like BOTH. How many students like NEITHER?","answer":5,"explain":"Students who like at least one: 18 + 14 - 7 = 25. So 30 - 25 = 5 like neither."},{"kind":"numeric","prompt":"The Grand Auditor's coin pile grows by 6 coins every day, starting with 10 coins on Day 1. How many coins will there be on Day 5?","answer":34,"explain":"Day 1: 10, Day 2: 16, Day 3: 22, Day 4: 28, Day 5: 34."},{"kind":"mcq","prompt":"Four data detectives — Ana, Ben, Cho, and Deep — each solved a different number of clues: 3, 5, 7, and 9 (in some order).\nClue 1: Ben solved more clues than Ana.\nClue 2: Cho solved the MOST clues of all four.\nClue 3: Deep solved exactly 3 clues.\nHow many clues did Cho solve?","options":["5","9","7","3"],"answer":1,"explain":"Cho solved the most clues out of everyone, and the highest number available is 9."}]}]}];